#define MAX_STRUCT_DEPTH 32

/* Per-parameter escape / @mem effects are tracked as one bit per parameter in
 * an `unsigned long long`, so only the first 64 parameters of a function carry
 * flow information. Every loop that writes such a mask is bounded by this. */
#define MAX_TRACKED_PARAMETERS 64

/* True when `path` is `dir` itself or sits underneath it. Both arguments must
 * already be canonicalized. Used to keep embed() from reaching outside the
 * source tree. */
static bool path_within_directory(const char *path, const char *directory) {
    size_t directory_length = strlen(directory);
    if (strlen(path) < directory_length) return false;
    if (path[directory_length] != '\0' && !gray_is_path_separator(path[directory_length])) return false;
    char prefix[4096];
    if (directory_length >= sizeof(prefix)) return false;
    memcpy(prefix, path, directory_length);
    prefix[directory_length] = '\0';
    return gray_path_equal(prefix, directory);
}

/* Helper: get the source file from an AST node's token, falling back to checker->file.
 * Imported nodes carry their original file path in token.file; main-file nodes have NULL. */
#define NODE_FILE(checker, node) ((node)->token.file ? (node)->token.file : (checker)->file)

/* Check if using_modules[using_index] is accessible from the current file being checked.
 * A using-module entry is accessible only if it was declared in the same file
 * that is currently being validated (prevents transitive import type leaking). */
static inline bool same_source_file(const char *left, const char *right) {
    /* Both NULL — both from main file context */
    if (!left && !right) return true;
    /* Both set — compare paths */
    return left && right && strcmp(left, right) == 0;
}

static inline bool using_module_accessible(TypeChecker *checker, int using_index) {
    const char *using_file = checker->using_module_files ? checker->using_module_files[using_index] : NULL;
    return same_source_file(using_file, checker->current_check_file);
}

/* True when imports[import_index] was written in the file being checked.
 * imported_modules[] lists every file's imports; a module is in scope only in
 * the file that imported it. */
static inline bool import_in_current_file(TypeChecker *checker, int import_index) {
    return same_source_file(checker->import_files[import_index], checker->current_check_file);
}

/* Mark a module imported by the current file as used. Returns true if found. */
static bool mark_import_used(TypeChecker *checker, const char *module_name) {
    for (int import_index = 0; import_index < checker->import_count; import_index++) {
        if (import_in_current_file(checker, import_index) &&
            strcmp(checker->imported_modules[import_index], module_name) == 0) {
            checker->is_import_used[import_index] = true;
            return true;
        }
    }
    return false;
}

/* Helper: get the user-facing display name for a declaration.
 * Import merging prefixes names (e.g. foo → mod_foo) but errors should
 * show the original name the user wrote. */
#define FUNCTION_DISPLAY_NAME(node) ((node)->data.function_declaration.original_name ? (node)->data.function_declaration.original_name : (node)->data.function_declaration.name)
#define VARIABLE_DISPLAY_NAME(node)  ((node)->data.variable_declaration.original_name  ? (node)->data.variable_declaration.original_name  : (node)->data.variable_declaration.name)
#define STRUCT_DISPLAY_NAME(node) ((node)->data.struct_declaration.original_name ? (node)->data.struct_declaration.original_name : (node)->data.struct_declaration.name)
#define ENUM_DISPLAY_NAME(node) ((node)->data.enum_declaration.original_name ? (node)->data.enum_declaration.original_name : (node)->data.enum_declaration.name)

/* --- Type Table (open-addressing hash, pointer keys) --- */

static uint32_t hash_pointer(const void *pointer) {
    uintptr_t hash_value = (uintptr_t)pointer;
    /* Fibonacci hashing; good distribution for pointer alignment */
    hash_value = ((hash_value >> 4) ^ hash_value) * 0x9E3779B9U;
    return (uint32_t)(hash_value ^ (hash_value >> 16));
}

static TypeTable *typetable_create(void) {
    TypeTable *table = xcalloc(1, sizeof(TypeTable));
    table->capacity = TYPE_TABLE_INITIAL_CAPACITY;
    table->nodes = xcalloc((size_t)table->capacity, sizeof(AstNode *));
    table->types = xcalloc((size_t)table->capacity, sizeof(GrayType *));
    return table;
}

static void typetable_set(TypeTable *table, AstNode *node, GrayType *type);

static void typetable_grow(TypeTable *table) {
    int old_capacity = table->capacity;
    AstNode **old_nodes = table->nodes;
    GrayType **old_types = table->types;

    table->capacity = old_capacity * 2;
    table->nodes = xcalloc((size_t)table->capacity, sizeof(AstNode *));
    table->types = xcalloc((size_t)table->capacity, sizeof(GrayType *));
    table->count = 0;

    for (int i = 0; i < old_capacity; i++) {
        if (old_nodes[i]) {
            typetable_set(table, old_nodes[i], old_types[i]);
        }
    }
    free(old_nodes);
    free(old_types);
}

static void typetable_set(TypeTable *table, AstNode *node, GrayType *type) {
    /* Grow at 70% load factor */
    if (table->count * 10 >= table->capacity * 7) {
        typetable_grow(table);
    }

    uint32_t mask = (uint32_t)(table->capacity - 1);
    uint32_t slot = hash_pointer(node) & mask;

    for (;;) {
        if (!table->nodes[slot]) {
            /* Empty slot; insert */
            table->nodes[slot] = node;
            table->types[slot] = type;
            table->count++;
            return;
        }
        if (table->nodes[slot] == node) {
            /* Already present; update */
            table->types[slot] = type;
            return;
        }
        slot = (slot + 1) & mask;
    }
}

GrayType *type_table_get(TypeTable *table, AstNode *node) {
    if (!table || !table->nodes) return NULL;

    uint32_t mask = (uint32_t)(table->capacity - 1);
    uint32_t slot = hash_pointer(node) & mask;

    for (;;) {
        if (!table->nodes[slot]) return NULL;
        if (table->nodes[slot] == node) return table->types[slot];
        slot = (slot + 1) & mask;
    }
}

/* Shared helpers for sorted-string-set lookups. */
static int string_pointer_compare(const void *left, const void *right) {
    return strcmp(*(const char *const *)left, *(const char *const *)right);
}
static bool string_set_contains(const char *const *sorted, int count, const char *name) {
    return bsearch(&name, sorted, (size_t)count, sizeof(const char *), string_pointer_compare) != NULL;
}


