/* Return the user-facing display string for an operator TokenType.
 * Used in error messages that embed the operator name. */
static const char *operator_display_name(TokenType operator) {
    switch (operator) {
    case TOKEN_PLUS: return "+";
    case TOKEN_MINUS: return "-";
    case TOKEN_ASTERISK: return "*";
    case TOKEN_SLASH: return "/";
    case TOKEN_PERCENT: return "%";
    case TOKEN_EQUAL: return "==";
    case TOKEN_NOT_EQUAL: return "!=";
    case TOKEN_LESS_THAN: return "<";
    case TOKEN_GREATER_THAN: return ">";
    case TOKEN_LESS_THAN_OR_EQUAL: return "<=";
    case TOKEN_GREATER_THAN_OR_EQUAL: return ">=";
    case TOKEN_AND: return "&&";
    case TOKEN_OR: return "||";
    case TOKEN_BANG: return "!";
    case TOKEN_BIT_AND: return "bit_and";
    case TOKEN_BIT_OR: return "bit_or";
    case TOKEN_BIT_XOR: return "bit_xor";
    case TOKEN_BIT_NOT: return "bit_not";
    case TOKEN_BIT_SHIFT_LEFT: return "bit_shift_left";
    case TOKEN_BIT_SHIFT_RIGHT: return "bit_shift_right";
    case TOKEN_INCREMENT: return "++";
    case TOKEN_DECREMENT: return "--";
    case TOKEN_CARET: return "^";
    case TOKEN_ASSIGN: return "=";
    case TOKEN_PLUS_ASSIGN: return "+=";
    case TOKEN_MINUS_ASSIGN: return "-=";
    case TOKEN_ASTERISK_ASSIGN: return "*=";
    case TOKEN_SLASH_ASSIGN: return "/=";
    case TOKEN_PERCENT_ASSIGN: return "%=";
    case TOKEN_IN: return "in";
    case TOKEN_NOT_IN: return "not_in";
    default: return "?";
    }
}

/* Forward declarations for type-name checks used by is_assignment_target */
static bool is_struct_name(TypeChecker *checker, const char *name);
static bool is_enum_name(TypeChecker *checker, const char *name);
static const char *checker_resolve_declaration_into(TypeChecker *checker, const char *written,
                                             char *buffer, size_t buffer_length);
static void checker_refresh_using(TypeChecker *checker);
static ResolveScope checker_scope(TypeChecker *checker);
static bool type_argument_names_a_type(TypeChecker *checker, const char *name);
static DeclarationEntry *checker_resolve_entry(TypeChecker *checker, const char *written);
static GrayType *resolve_function_reference(TypeChecker *checker, AstNode *node);
static bool reference_names_function(TypeChecker *checker, AstNode *argument);

/* True if the expression is an assignment target (something with a stable
 * address): a variable, a field of an assignment target, an index into an
 * assignment target, or a pointer dereference. Used by addr(), raw(), and
 * ref() to reject literals, call results, arithmetic expressions, and type
 * names — none of which have an address to take. */
static bool is_assignment_target(TypeChecker *checker, AstNode *expression) {
    if (!expression) return false;
    switch (expression->kind) {
    case NODE_LABEL: {
        const char *name = expression->data.label.value;
        if (is_builtin_type_name(name)) return false;
        if (is_struct_name(checker, name)) return false;
        if (is_enum_name(checker, name)) return false;
        return true;
    }
    case NODE_MEMBER_EXPRESSION:  return is_assignment_target(checker, expression->data.member.object);
    case NODE_INDEX_EXPRESSION:   return is_assignment_target(checker, expression->data.index_expression.left);
    case NODE_POSTFIX_EXPRESSION:
        /* p^ (dereference) is an assignment target */
        return expression->data.postfix.operator == TOKEN_CARET;
    default:                return false;
    }
}

/* Walk an assignment target expression chain and return the root variable name.
 * Returns NULL if the chain passes through a pointer dereference (^),
 * because the pointed-to memory is independent of the pointer variable's
 * mutability. */
static const char *assignment_target_root_name(AstNode *expression) {
    if (!expression) return NULL;
    switch (expression->kind) {
    case NODE_LABEL:       return expression->data.label.value;
    case NODE_MEMBER_EXPRESSION: return assignment_target_root_name(expression->data.member.object);
    case NODE_INDEX_EXPRESSION:  return assignment_target_root_name(expression->data.index_expression.left);
    case NODE_POSTFIX_EXPRESSION:
        if (expression->data.postfix.operator == TOKEN_CARET)
            return NULL; /* pointer deref: memory is not the const variable */
        return NULL;
    default: return NULL;
    }
}

/* Depth of the scope declaring `name`, biased by +1 so 0 means "not found".
 * Deeper means shorter-lived: a pointer may only hold an address whose
 * origin depth is at most the pointer's own. */
static int symbol_scope_depth(Scope *scope, const char *name) {
    for (Scope *current = scope; current; current = current->parent)
        if (scope_lookup_local(current, name)) return current->depth + 1;
    return 0;
}

/* Lifetime origin of a call result whose value is forwarded from one of the
 * call's arguments (per the callee's returns_parameter_address summary). Defined
 * below register_function; forward-declared here for pointer_origin_of. */
static int call_result_origin(TypeChecker *checker, AstNode *call,
                              const char **out_name);

/* Deepest origin among a call's own arguments — the conservative fallback
 * for a call this checker cannot analyze precisely: a stdlib module
 * function or bare builtin, neither of which has a FunctionSignature or a computed
 * escape summary the way a user function does. Only meaningful when the
 * caller has already confirmed there is no such summary to fall back on
 * instead. Defined below expression_origin; forward-declared here for
 * pointer_origin_of and container_literal_origin. */
static int stdlib_call_argument_origin(TypeChecker *checker, AstNode *call,
                                  const char **out_name);

/* The user-defined function `call` targets, or NULL for anything this
 * checker keeps no FunctionSignature for (a stdlib module call, a bare builtin).
 * Defined further down; forward-declared here for pointer_origin_of. */
static FunctionSignature *resolve_call_signature(TypeChecker *checker, AstNode *call);

/* If `value` produces a pointer with a known lifetime origin, report that
 * origin's scope depth and name. Covers the direct form addr(x)/raw(x), a
 * pointer variable that already carries an origin, and a call result that
 * forwards one of its pointer arguments — so an address that is laundered
 * through any number of intermediates or through a function call stays
 * tracked. */
static int pointer_origin_of(TypeChecker *checker, AstNode *value,
                             const char **out_name) {
    if (!value) return 0;
    if (value->kind == NODE_CALL_EXPRESSION &&
        value->data.call.function->kind == NODE_LABEL &&
        value->data.call.argument_count == 1 &&
        (strcmp(value->data.call.function->data.label.value, "addr") == 0 ||
         strcmp(value->data.call.function->data.label.value, "raw") == 0 ||
         strcmp(value->data.call.function->data.label.value, "ref") == 0)) {
        const char *root = assignment_target_root_name(value->data.call.arguments[0]);
        if (!root) return 0;
        int depth = symbol_scope_depth(checker->current_scope, root);
        if (depth) *out_name = root;
        return depth;
    }
    if (value->kind == NODE_LABEL) {
        Symbol *source_symbol = scope_lookup(checker->current_scope, value->data.label.value);
        if (source_symbol && source_symbol->origin_depth) {
            *out_name = source_symbol->origin_name;
            return source_symbol->origin_depth;
        }
        /* A bare struct/array/map variable, taken as a whole (not indexed
         * into): its own buried origin, from when it was declared or last
         * assigned a literal/copy() holding addr(local). Unlike the indexed
         * read below, no TYPE_KIND_POINTER guard is needed — the origin belongs to
         * something inside the aggregate, not to `value` itself. */
        if (source_symbol && source_symbol->field_origin_depth) {
            *out_name = source_symbol->field_origin_name;
            return source_symbol->field_origin_depth;
        }
    }
    /* An element/field read *out of* a container that was built from a
     * literal holding addr(local) — `a[0]`, `b.p`. The container's buried
     * origin travels with the value that comes back out, but only when the
     * slot is itself a pointer; a copied scalar field is safe. */
    if (value->kind == NODE_INDEX_EXPRESSION || value->kind == NODE_MEMBER_EXPRESSION) {
        const char *root = assignment_target_root_name(value);
        if (root) {
            Symbol *symbol = scope_lookup(checker->current_scope, root);
            if (symbol && symbol->field_origin_depth) {
                GrayType *value_type = resolve_expression(checker, value);
                if (value_type && value_type->kind == TYPE_KIND_POINTER) {
                    *out_name = symbol->field_origin_name;
                    return symbol->field_origin_depth;
                }
            }
        }
    }
    if (value->kind == NODE_CALL_EXPRESSION) {
        int root_depth = call_result_origin(checker, value, out_name);
        /* call_result_origin comes back 0 both when a resolved user
         * function's summary says nothing escapes, and when there is no
         * FunctionSignature to summarise at all (a stdlib module call, a bare
         * builtin). Only the latter falls back to the conservative
         * arguments-based guess — resolve_call_signature() tells them apart. */
        if (!root_depth && !resolve_call_signature(checker, value))
            root_depth = stdlib_call_argument_origin(checker, value, out_name);
        return root_depth;
    }
    return 0;
}

/* True if the access path contains a map index, e.g. ref(m["k"]) or
 * ref(m["k"].field) or ref(rows[i].cells["k"]). Map values relocate on
 * rehash so a pointer to one is unsafe. */
static bool path_contains_map_index(TypeChecker *checker, AstNode *expression) {
    if (!expression) return false;
    switch (expression->kind) {
    case NODE_MEMBER_EXPRESSION:
        return path_contains_map_index(checker, expression->data.member.object);
    case NODE_INDEX_EXPRESSION: {
        GrayType *left_type = resolve_expression(checker, expression->data.index_expression.left);
        if (left_type && left_type->kind == TYPE_KIND_MAP) return true;
        return path_contains_map_index(checker, expression->data.index_expression.left);
    }
    case NODE_POSTFIX_EXPRESSION:
        return path_contains_map_index(checker, expression->data.postfix.left);
    default:
        return false;
    }
}

/* --- Struct info helpers --- */

/* Is this type name already taken by a different declaration? The registries
 * fill one kind at a time, so a struct/enum collision is visible in the
 * symbol table before either registry can see both halves of it. */
static bool type_name_already_declared(TypeChecker *checker, const char *name,
                                       const AstNode *statement) {
    DeclarationEntry *entry = checker_resolve_entry(checker, name);
    return entry && entry->ast_node && entry->ast_node != statement &&
           (entry->kind == DECLARATION_STRUCT || entry->kind == DECLARATION_ENUM ||
            entry->kind == DECLARATION_ALIAS);
}

/* Anything registered without a source declaration of its own — a compiler
 * provided type, a stdlib opaque type — still needs an entry, so that every
 * lookup goes through the symbol table and none through a name array. */
static void adopt_registration(TypeChecker *checker, DeclarationKind kind,
                               const char *name, int index) {
    if (!checker->modules) return;
    DeclarationEntry *existing = module_table_find_mangled(checker->modules, name);
    if (existing) {
        /* A stdlib opaque type is declared by its module before its details
         * are registered here. Point the existing entry at them rather than
         * leaving it detail-less and shadowing this registration. */
        if (existing->kind == kind && existing->registry_index < 0)
            existing->registry_index = index;
        return;
    }
    DeclarationEntry *entry = module_table_declare_synthetic(checker->modules, NULL, kind,
                                                      name, checker->file);
    if (entry) entry->registry_index = index;
}

/* The unprefixed alias `using` publishes for a declaration stands for that
 * declaration, so it has to carry its visibility. Left public, an alias for a
 * private struct or enum was reachable by a bare name from a file that cannot
 * name it at all — which is how `private` stopped meaning anything on a type
 * once its file was used. */
static void inherit_declaration_visibility(TypeChecker *checker, const char *from, const char *target_entry_name) {
    if (!checker->modules) return;
    DeclarationEntry *source_entry = module_table_find_mangled(checker->modules, from);
    DeclarationEntry *destination_entry = module_table_find_mangled(checker->modules, target_entry_name);
    if (!source_entry || !destination_entry || source_entry == destination_entry) return;
    destination_entry->visibility = source_entry->visibility;
    destination_entry->origin_file = source_entry->origin_file;
}

static void register_struct(TypeChecker *checker, const char *name,
    const char *display_name,
    const char **field_names, GrayType **field_types, int field_count) {
    GROW_ARRAY(checker->structs, checker->struct_count, checker->struct_capacity);
    adopt_registration(checker, DECLARATION_STRUCT, name, checker->struct_count);
    StructInfo *struct_info = &checker->structs[checker->struct_count++];
    struct_info->struct_name = name;
    struct_info->display_name = display_name ? display_name : name;
    struct_info->field_names = field_names;
    struct_info->field_types = field_types;
    struct_info->field_count = field_count;
    struct_info->is_deprecated = false;
    struct_info->deprecated_message = NULL;
}


/* The lookup helpers below take a name as written — a bare `Foo` inside its
 * own module, a `using`'d `Foo`, or a qualified `lib.Foo` — and resolve it to
 * the registry spelling before looking it up. Doing it here rather than at
 * each call site is what lets a reference stay as written all the way from
 * the parser. Resolution is idempotent: a name that names no declaration,
 * an already-mangled key included, comes back unchanged. */
static StructInfo *find_struct(TypeChecker *checker, const char *name) {
    DeclarationEntry *entry = checker_resolve_entry(checker, name);
    if (!entry) entry = module_table_find_mangled(checker->modules, name);
    if (entry && entry->kind == DECLARATION_STRUCT && entry->registry_index >= 0 &&
        entry->registry_index < checker->struct_count)
        return &checker->structs[entry->registry_index];
    return NULL;
}

static bool is_struct_name(TypeChecker *checker, const char *name) {
    return find_struct(checker, name) != NULL;
}



/* Returns the original index of the named enum via O(log n) bsearch, or -1. */
static int find_enum_index(TypeChecker *checker, const char *name) {
    DeclarationEntry *entry = checker_resolve_entry(checker, name);
    if (!entry) entry = module_table_find_mangled(checker->modules, name);
    if (entry && entry->kind == DECLARATION_ENUM && entry->registry_index >= 0 &&
        entry->registry_index < checker->enum_count)
        return entry->registry_index;
    return -1;
}

static bool is_enum_name(TypeChecker *checker, const char *name) {
    return find_enum_index(checker, name) >= 0;
}

/* Best-effort unqualified form of a type name that has no registry entry
 * to recover a proper display name from — e.g. an undefined type, where
 * read_type_name() mangled a written "mod.Type" into "mod_Type" and
 * there's no struct/enum to look the original spelling up on. Mirrors the
 * module-prefix heuristic already used to resolve module-prefixed lookups
 * in typechecker_type_from_name(). */
static const char *unqualified_display_name(const char *name) {
    if (!name) return name;
    /* As written: mod.Type. */
    const char *last_dot = strchr(name, '.');
    if (last_dot && last_dot[1] >= 'A' && last_dot[1] <= 'Z') return last_dot + 1;
    /* As mangled: mod_Type. Split at the last '_' so a module name that
     * contains one keeps its whole prefix. */
    const char *underscore = strrchr(name, '_');
    if (underscore && underscore[1] >= 'A' && underscore[1] <= 'Z') return underscore + 1;
    return name;
}

/* The name the programmer wrote for a struct, never the module-prefixed
 * lookup key. Diagnostics and namespace-collision checks must use this. */
static const char *struct_display_name(TypeChecker *checker, const char *name) {
    StructInfo *struct_info = find_struct(checker, name);
    return struct_info ? struct_info->display_name : unqualified_display_name(name);
}

/* As struct_display_name, for enums. */
static const char *enum_display_name(TypeChecker *checker, const char *name) {
    int i = find_enum_index(checker, name);
    if (i < 0) return unqualified_display_name(name);
    return checker->enum_display_names[i] ? checker->enum_display_names[i] : checker->enum_names[i];
}

/* Type identity is the resolved declaration, not the spelling of the
 * reference. Both names arrive already mapped onto their registry spelling,
 * so lib_Foo and objects_Foo are the different types they are — comparing
 * display names made every module's `Foo` the same `Foo`, and let one
 * module's struct be passed where another's was expected. */
static bool typechecker_same_struct_type(TypeChecker *checker, const char *left, const char *right) {
    (void)checker;
    return left == right || strcmp(left, right) == 0;
}
static bool typechecker_enum_is_error_code(TypeChecker *checker, const char *name);
static bool typechecker_same_enum_type(TypeChecker *checker, const char *left, const char *right) {
    if (left == right || strcmp(left, right) == 0) return true;
    /* A #error_code enum value is interchangeable with an ErrorCode value, but
     * only with ErrorCode — each concrete #error_code enum stays its own type,
     * so NetErr and DbErr do not unify with each other (STANDARD 10.5). */
    if (!typechecker_enum_is_error_code(checker, left) ||
        !typechecker_enum_is_error_code(checker, right)) return false;
    return strcmp(left, "ErrorCode") == 0 || strcmp(right, "ErrorCode") == 0;
}
/* Compare array element type names accounting for module-prefixed struct
 * aliases (e.g. "Item" vs "utils_Item" should match). */
static bool typechecker_same_array_element(TypeChecker *checker, const char *left, const char *right) {
    if (strcmp(left, right) == 0) return true;
    GrayType *argument_type = type_from_name(left);
    GrayType *base_type = type_from_name(right);
    if (argument_type && base_type && argument_type->kind == TYPE_KIND_STRUCT && base_type->kind == TYPE_KIND_STRUCT)
        return typechecker_same_struct_type(checker, left, right);
    if (argument_type && base_type && argument_type->kind == TYPE_KIND_ENUM && base_type->kind == TYPE_KIND_ENUM)
        return typechecker_same_enum_type(checker, left, right);
    return false;
}

/* Returns true if the named enum is string-backed. */
static bool typechecker_enum_is_string(TypeChecker *checker, const char *name) {
    int i = find_enum_index(checker, name);
    return i >= 0 && checker->is_enum_string[i];
}

/* Returns true if the named enum is a tagged enum (has payload variants). */
static bool typechecker_enum_is_tagged(TypeChecker *checker, const char *name) {
    int i = find_enum_index(checker, name);
    return i >= 0 && checker->is_enum_tagged[i];
}

static bool typechecker_enum_is_flags(TypeChecker *checker, const char *name) {
    int i = find_enum_index(checker, name);
    return i >= 0 && checker->is_enum_flags[i];
}

/* True for the builtin open enum "ErrorCode" and for any user enum carrying
 * #error_code. Values of these enums share one variant/value space. */
static bool typechecker_enum_is_error_code(TypeChecker *checker, const char *name) {
    if (!name) return false;
    if (strcmp(name, "ErrorCode") == 0) return true;
    for (int i = 0; i < checker->error_code_enum_count; i++) {
        if (strcmp(checker->error_code_enum_names[i], name) == 0) return true;
    }
    return false;
}

/* How many declared types go by this user-facing name. Two means a message
 * printing the bare name cannot tell them apart. */
static int display_name_count(TypeChecker *checker, const char *display) {
    int count = 0;
    for (int i = 0; i < checker->struct_count; i++) {
        const char *display_name = checker->structs[i].display_name
            ? checker->structs[i].display_name : checker->structs[i].struct_name;
        if (display_name && strcmp(display_name, display) == 0) count++;
    }
    for (int i = 0; i < checker->enum_count; i++) {
        const char *display_name = checker->enum_display_names[i]
            ? checker->enum_display_names[i] : checker->enum_names[i];
        if (display_name && strcmp(display_name, display) == 0) count++;
    }
    return count;
}

/* The name a diagnostic gives a declared type: as written, qualified by its
 * module when another declaration goes by the same name. Two modules' `Color`
 * are different types, and "cannot assign Color to Color" tells the reader
 * nothing about which is which. `key` is the registry spelling, `display` the
 * name looked up from it — equal pointers mean no declaration was found. */
static const char *qualify_ambiguous_name(TypeChecker *checker,
                                          const char *lookup_key, const char *display) {
    if (display == lookup_key || display_name_count(checker, display) < 2) return display;
    DeclarationEntry *entry = checker_resolve_entry(checker, lookup_key);
    if (!entry) entry = module_table_find_mangled(checker->modules, lookup_key);
    if (!entry || !entry->module_name || !entry->module_name[0]) return display;
    static char qualified_buffers[4][TYPE_NAME_MAX];
    static int qualified_slot = 0;
    char *qualified_name = qualified_buffers[qualified_slot];
    qualified_slot = (qualified_slot + 1) & 3;
    snprintf(qualified_name, sizeof(qualified_buffers[0]), "%s.%s", entry->module_name, display);
    return qualified_name;
}

/* A type name fit to print in a diagnostic — for struct/enum types this
 * is the user-facing name, never the module-prefixed lookup key. Composite
 * types (pointers, arrays, maps) recurse into their inner types so that
 * e.g. ^myutils_Thing displays as ^Thing. */
static const char *type_display_name(TypeChecker *checker, GrayType *type) {
    if (!type) return type_name(type);
    if (type->kind == TYPE_KIND_STRUCT && type->name)
        return qualify_ambiguous_name(checker, type->name, struct_display_name(checker, type->name));
    if (type->kind == TYPE_KIND_ENUM && type->name)
        return qualify_ambiguous_name(checker, type->name, enum_display_name(checker, type->name));
    if (type->kind == TYPE_KIND_POINTER && type->name) {
        const char *inner = struct_display_name(checker, type->name);
        if (inner == type->name) inner = enum_display_name(checker, type->name);
        if (inner != type->name) {
            static char pointer_buffers[4][TYPE_NAME_MAX];
            static int pointer_slot = 0;
            char *display_name_text = pointer_buffers[pointer_slot];
            pointer_slot = (pointer_slot + 1) & 3;
            snprintf(display_name_text, sizeof(pointer_buffers[0]), "^%s",
                qualify_ambiguous_name(checker, type->name, inner));
            return display_name_text;
        }
    }
    if (type->kind == TYPE_KIND_ARRAY && type->element_type) {
        const char *inner = struct_display_name(checker, type->element_type);
        if (inner == type->element_type) inner = enum_display_name(checker, type->element_type);
        if (inner != type->element_type) {
            static char array_buffers[4][TYPE_NAME_MAX];
            static int array_slot = 0;
            char *display_name_text = array_buffers[array_slot];
            array_slot = (array_slot + 1) & 3;
            snprintf(display_name_text, sizeof(array_buffers[0]), "[%s]",
                qualify_ambiguous_name(checker, type->element_type, inner));
            return display_name_text;
        }
    }
    return type_name(type);
}

/* Resolve an import alias to the actual module name */
static const char *typechecker_resolve_alias(TypeChecker *checker, const char *name) {
    return module_table_resolve_alias(checker->modules, name);
}

/* Position of the first `sep` in `s` that sits at bracket/paren nesting
 * depth 0, or NULL if there is none. Used to split composite type strings
 * (`map[K:V]`, `func(P,...)->R`, `[Elem,N]`) without tripping on separators
 * inside nested composites. */
static char *alias_top_level_separator(char *spelling, char separator) {
    int depth = 0;
    for (char *cursor = spelling; *cursor; cursor++) {
        if (*cursor == '[' || *cursor == '(') depth++;
        else if (*cursor == ']' || *cursor == ')') depth--;
        else if (*cursor == separator && depth == 0) return cursor;
    }
    return NULL;
}

static const char *resolve_type_alias(TypeChecker *checker, const char *name);

/* Resolve every top-level comma-separated type name in `list` (used as a
 * mutable scratch buffer), writing the rebuilt list into `out`. A leading
 * `&` on a segment (a mutable func parameter) is preserved. Returns 1 when
 * at least one element resolved to a different name, 0 when nothing
 * changed, -1 on buffer overflow (`out` unusable). */
static int alias_resolve_type_list(TypeChecker *checker, char *list,
                                   char *resolved_list, size_t out_size) {
    size_t position = 0;
    bool changed = false;
    char *segment = list;
    resolved_list[0] = '\0';
    while (segment && *segment) {
        char *comma = alias_top_level_separator(segment, ',');
        if (comma) *comma = '\0';
        const char *ampersand = "";
        char *type_parameter = segment;
        if (*type_parameter == '&') { ampersand = "&"; type_parameter++; }
        const char *resolved_part = resolve_type_alias(checker, type_parameter);
        if (resolved_part != type_parameter) changed = true;
        int part_count = snprintf(resolved_list + position, out_size - position, "%s%s%s",
                         position ? "," : "", ampersand, resolved_part);
        if (part_count < 0 || (size_t)part_count >= out_size - position) return -1;
        position += (size_t)part_count;
        segment = comma ? comma + 1 : NULL;
    }
    return changed ? 1 : 0;
}

/* Resolve a type alias name to the underlying type name.
 * Follows chains transitively with a depth limit of 32.
 * Handles pointer (^Name), array ([Name] / [Name,N]), map (map[K:V]) and
 * func signature (func(P,...)->R) types, recursing into every type slot.
 * Returns the original name if it is not an alias. */
static const char *resolve_type_alias(TypeChecker *checker, const char *name) {
    if (!name) return name;

    /* Handle pointer types: ^Alias → ^Resolved */
    if (name[0] == '^') {
        const char *inner = resolve_type_alias(checker, name + 1);
        if (inner != name + 1) {
            size_t length = strlen(inner) + 2;
            char *buffer = arena_allocate(checker->arena, length);
            snprintf(buffer, length, "^%s", inner);
            return buffer;
        }
        return name;
    }

    /* Handle array types: [Alias] and fixed-size [Alias,N] → [Resolved(,N)] */
    if (name[0] == '[') {
        size_t name_length = strlen(name);
        if (name_length > 2 && name[name_length - 1] == ']') {
            /* Extract inner type name (skip [ and ]) */
            char inner_buffer[256];
            size_t inner_length = name_length - 2;
            if (inner_length < sizeof(inner_buffer)) {
                memcpy(inner_buffer, name + 1, inner_length);
                inner_buffer[inner_length] = '\0';
                /* Fixed-size array: split off the trailing ",N" size. */
                char *size_comma = alias_top_level_separator(inner_buffer, ',');
                const char *size_suffix = "";
                char size_text[64];
                if (size_comma) {
                    snprintf(size_text, sizeof(size_text), ",%s", size_comma + 1);
                    size_suffix = size_text;
                    *size_comma = '\0';
                }
                const char *resolved_inner = resolve_type_alias(checker, inner_buffer);
                if (resolved_inner != inner_buffer) {
                    size_t array_spelling_length = strlen(resolved_inner) + strlen(size_suffix) + 3;
                    char *buffer = arena_allocate(checker->arena, array_spelling_length);
                    snprintf(buffer, array_spelling_length, "[%s%s]", resolved_inner, size_suffix);
                    return buffer;
                }
            }
        }
        return name;
    }

    /* Handle map types: map[K:V] → map[Resolved:Resolved] */
    if (strncmp(name, "map[", 4) == 0) {
        size_t name_length = strlen(name);
        if (name_length > 5 && name[name_length - 1] == ']') {
            char inner_buffer[256];
            size_t inner_length = name_length - 5;
            if (inner_length < sizeof(inner_buffer)) {
                memcpy(inner_buffer, name + 4, inner_length);
                inner_buffer[inner_length] = '\0';
                char *colon = alias_top_level_separator(inner_buffer, ':');
                if (colon) {
                    *colon = '\0';
                    const char *key_part = resolve_type_alias(checker, inner_buffer);
                    const char *value_part = resolve_type_alias(checker, colon + 1);
                    if (key_part != inner_buffer || value_part != colon + 1) {
                        size_t map_spelling_length = strlen(key_part) + strlen(value_part) + 7;
                        char *buffer = arena_allocate(checker->arena, map_spelling_length);
                        snprintf(buffer, map_spelling_length, "map[%s:%s]", key_part, value_part);
                        return buffer;
                    }
                }
            }
        }
        return name;
    }

    /* Handle func signatures: func(P,...)->R → func(Resolved,...)->Resolved */
    if (strncmp(name, "func(", 5) == 0) {
        int depth = 0;
        const char *close = NULL;
        for (const char *cursor = name + 4; *cursor; cursor++) {
            if (*cursor == '(') depth++;
            else if (*cursor == ')' && --depth == 0) { close = cursor; break; }
        }
        if (close) {
            size_t parameter_list_length = (size_t)(close - (name + 5));
            const char *tail = close + 1;
            const char *return_text = (strncmp(tail, "->", 2) == 0) ? tail + 2 : NULL;
            char parameter_list[256];
            char rebuilt[256];
            if (parameter_list_length < sizeof(parameter_list)) {
                memcpy(parameter_list, name + 5, parameter_list_length);
                parameter_list[parameter_list_length] = '\0';
                int parameters_changed =
                    alias_resolve_type_list(checker, parameter_list, rebuilt, sizeof(rebuilt));
                const char *resolved_return_text = return_text ? resolve_type_alias(checker, return_text) : NULL;
                bool was_return_changed = (return_text && resolved_return_text != return_text);
                if (parameters_changed >= 0 && (parameters_changed == 1 || was_return_changed)) {
                    size_t map_spelling_length = strlen(rebuilt) + (resolved_return_text ? strlen(resolved_return_text) : 0) + 10;
                    char *buffer = arena_allocate(checker->arena, map_spelling_length);
                    if (resolved_return_text) snprintf(buffer, map_spelling_length, "func(%s)->%s", rebuilt, resolved_return_text);
                    else snprintf(buffer, map_spelling_length, "func(%s)", rebuilt);
                    return buffer;
                }
            }
        }
        return name;
    }

    for (int depth = 0; depth < 32; depth++) {
        bool found = false;
        for (int i = 0; i < checker->type_alias_count; i++) {
            if (strcmp(checker->type_alias_names[i], name) == 0) {
                name = checker->type_alias_targets[i];
                found = true;
                break;
            }
        }
        if (!found) break;
        /* A target that is itself a container — alias Counts = [Count],
         * alias M = map[string:I] — has to go back through the branches
         * above, or the alias nested inside it never gets followed. */
        if (name[0] == '^' || name[0] == '[' ||
            strncmp(name, "map[", 4) == 0 || strncmp(name, "func(", 5) == 0)
            return resolve_type_alias(checker, name);
    }
    return name;
}

/* Format a diagnostic message string into the arena (only called in error paths). */
static char *typechecker_format(TypeChecker *checker, const char *format, ...) {
    char buffer[MESSAGE_BUFFER_SIZE];
    va_list arguments;
    va_start(arguments, format);
    vsnprintf(buffer, sizeof(buffer), format, arguments);
    va_end(arguments);
    return arena_copy_string(checker->arena, buffer);
}

/* Report `code` at `node`'s position. `msg` is a fully-built, arena-owned
 * string (typically from typechecker_format). Callers pass `code` as a string
 * literal so scripts/check_error_codes.gray still sees every emit site. */
static void typechecker_error_at(TypeChecker *checker, const char *code, AstNode *node, char *message) {
    diagnostic_error_message(checker->diagnostics, code, message,
        NODE_FILE(checker, node), node->token.line, node->token.column, 0);
}

/* The sized type that replaced a removed built-in type name, or NULL. */
static const char *removed_type_replacement(const char *name) {
    if (strcmp(name, "int") == 0)   return "i64";
    if (strcmp(name, "uint") == 0)  return "u64";
    if (strcmp(name, "float") == 0) return "f64";
    if (strcmp(name, "byte") == 0)  return "u8";
    return NULL;
}

/* Help text for an undefined type name that was once built in, or NULL. */
static char *removed_type_help(TypeChecker *checker, const char *name) {
    const char *replacement = removed_type_replacement(name);
    if (!replacement) return NULL;
    return typechecker_format(checker, "use '%s', or declare 'alias %s = %s'",
                              replacement, name, replacement);
}

/* E4016 with the registry message for an undefined type name. */
static void typechecker_error_undefined_type(TypeChecker *checker, AstNode *node, const char *name) {
    char *help = removed_type_help(checker, name);
    if (help)
        diagnostic_error_code_formatted_help(checker->diagnostics, "E4016",
            NODE_FILE(checker, node), node->token.line, node->token.column, 0, help, name);
    else
        diagnostic_error_code_formatted(checker->diagnostics, "E4016",
            NODE_FILE(checker, node), node->token.line, node->token.column, 0, name);
}

/* Emit helpers for the type-mismatch family. Each pins one code so the
 * situation stays 1:1 with its diagnostic (see scripts/check_error_codes.gray). */
static void typechecker_error_assign_type(TypeChecker *checker, AstNode *node, char *message) {
    typechecker_error_at(checker, "E3001", node, message);
}

static void typechecker_error_argument_type(TypeChecker *checker, AstNode *argument_node, char *message) {
    typechecker_error_at(checker, "E5026", argument_node, message);
}

static void typechecker_error_arity(TypeChecker *checker, AstNode *node, char *message) {
    typechecker_error_at(checker, "E5008", node, message);
}

static AstNode *find_struct_in_program(TypeChecker *checker, const char *name);

static GrayType *struct_field_type(TypeChecker *checker, const char *struct_name, const char *field) {
    StructInfo *struct_info = find_struct(checker, struct_name);
    /* for mangled generic struct names (Pair__int), fall back
     * to the base name (Pair) since fields are registered there.
     * When the field type is "?", substitute the concrete binding
     * extracted from the mangled suffix. */
    const char *generic_binding = NULL;
    if (!struct_info && struct_name) {
        const char *dunder = strstr(struct_name, "__");
        if (dunder) {
            char base[MESSAGE_BUFFER_SIZE];
            size_t prefix_length = (size_t)(dunder - struct_name);
            if (prefix_length < sizeof(base)) {
                memcpy(base, struct_name, prefix_length);
                base[prefix_length] = '\0';
                struct_info = find_struct(checker, base);
                generic_binding = dunder + 2;
            }
        }
    }
    if (!struct_info) return &TYPE_UNKNOWN;
    for (int i = 0; i < struct_info->field_count; i++) {
        if (strcmp(struct_info->field_names[i], field) == 0) {
            /* if the field type is ? (registered as TYPE_KIND_UNKNOWN)
             * and we have a generic binding from the mangled name,
             * substitute to the concrete type. Check the raw declaration
             * type_name since the resolved GrayType lost the "?" marker. */
            if (generic_binding && struct_info->field_types[i]->kind == TYPE_KIND_UNKNOWN) {
                /* Find the raw struct declaration to check the field type_name */
                if (checker->program) {
                    AstNode *declaration = find_struct_in_program(checker,
                        struct_name); /* try mangled first */
                    if (!declaration) {
                        /* Extract base name and try again */
                        const char *double_underscore = strstr(struct_name, "__");
                        if (double_underscore) {
                            char base_name[MESSAGE_BUFFER_SIZE];
                            size_t base_length = (size_t)(double_underscore - struct_name);
                            if (base_length < sizeof(base_name)) {
                                memcpy(base_name, struct_name, base_length);
                                base_name[base_length] = '\0';
                                declaration = find_struct_in_program(checker, base_name);
                            }
                        }
                    }
                    if (declaration) {
                        for (int field_index = 0; field_index < declaration->data.struct_declaration.field_count; field_index++) {
                            if (strcmp(declaration->data.struct_declaration.fields[field_index].name, field) == 0 &&
                                declaration->data.struct_declaration.fields[field_index].type_name &&
                                strchr(declaration->data.struct_declaration.fields[field_index].type_name, '?')) {
                                return type_from_name(generic_binding);
                            }
                        }
                    }
                }
            }
            return struct_info->field_types[i];
        }
    }
    return &TYPE_UNKNOWN;
}

/* --- Function signature helpers --- */

static bool type_name_has_wildcard(const char *type_name) {
    if (!type_name) return false;
    for (const char *cursor = type_name; *cursor; cursor++) {
        if (*cursor == '?') return true;
    }
    return false;
}

static void register_function(TypeChecker *checker, const char *name,
    GrayType **parameter_types, int parameter_count,
    GrayType **return_types, int return_count) {
    GROW_ARRAY(checker->functions, checker->function_count, checker->function_capacity);
    adopt_registration(checker, DECLARATION_FUNCTION, name, checker->function_count);
    FunctionSignature *function_signature = &checker->functions[checker->function_count++];
    function_signature->name = name;
    function_signature->parameter_types = parameter_types;
    function_signature->parameter_count = parameter_count;
    function_signature->return_types = return_types;
    function_signature->return_count = return_count;
    function_signature->was_used = false;
    function_signature->definition_line = 0;
    function_signature->is_private = false;
    function_signature->is_generic = false;
    function_signature->is_discard = false;
    function_signature->declaration = NULL;
    function_signature->escape_state = 0;
    function_signature->returns_parameter_address = 0;
    memset(function_signature->parameter_escape_into, PARAMETER_ESCAPE_NONE, sizeof function_signature->parameter_escape_into);
    memset(function_signature->parameter_escape_global_name, 0, sizeof function_signature->parameter_escape_global_name);
    memset(function_signature->parameter_escape_via_function, -1, sizeof function_signature->parameter_escape_via_function);
    function_signature->passes_parameter_to_extern = 0;
    function_signature->writes_through_parameter = 0;
    function_signature->can_return_const_pointer = false;
    function_signature->mem_state = 0;
    function_signature->destroys_parameter_arena = 0;
    function_signature->resets_parameter_arena = 0;
    memset(function_signature->mem_parameter_field, 0, sizeof function_signature->mem_parameter_field);
    function_signature->returns_parameter_mem_allocation = 0;
    function_signature->returns_parameter_mem_allocation_field = 0;
    function_signature->instantiations = NULL;
    function_signature->instantiation_calls = NULL;
    function_signature->instantiation_count = 0;
    function_signature->instantiation_capacity = 0;
}

/* Substitute '?' with `concrete` in a type string and return a heap copy.
 * Returns a strdup of the original if no wildcard is present. */
static char *substitute_wildcard(const char *source, const char *concrete) {
    if (!source) return NULL;
    if (!type_name_has_wildcard(source)) return strdup(source);
    size_t concrete_length = strlen(concrete);
    size_t length = 0;
    for (const char *cursor = source; *cursor; cursor++) length += (*cursor == '?') ? concrete_length : 1;
    char *output = xmalloc(length + 1);
    char *write_cursor = output;
    for (const char *cursor = source; *cursor; cursor++) {
        if (*cursor == '?') { memcpy(write_cursor, concrete, concrete_length); write_cursor += concrete_length; }
        else *write_cursor++ = *cursor;
    }
    *write_cursor = '\0';
    return output;
}

/* Find the top-level ':' inside a "map[K:V]" type string, skipping nested
 * brackets. Sets key_out/key_len and val_out/val_len on success. */
static bool parse_map_key_value(const char *type_name,
                              const char **key_out, size_t *key_length,
                              const char **value_out, size_t *value_length) {
    if (strncmp(type_name, "map[", 4) != 0) return false;
    const char *start = type_name + 4;
    int depth = 0;
    const char *colon = NULL;
    for (const char *cursor = start; *cursor && !(depth == 0 && *cursor == ']'); cursor++) {
        if      (*cursor == '[')                   depth++;
        else if (*cursor == ']')                   depth--;
        else if (*cursor == ':' && depth == 0) { colon = cursor; break; }
    }
    if (!colon) return false;
    *key_out = start;
    *key_length = (size_t)(colon - start);
    *value_out = colon + 1;
    const char *end_cursor = type_name + strlen(type_name) - 1;
    if (*end_cursor != ']') return false;
    *value_length = (size_t)(end_cursor - *value_out);
    return true;
}

/* Recursive string-based wildcard unifier.
 * Matches param_tn (containing '?') against the concrete type string
 * arg_tn and returns a heap-allocated string for the type '?' binds to,
 * or NULL on shape mismatch. Recurses into arrays and maps so nested
 * composites like [[?]], [map[string:?]], and map[string:[?]] are handled.
 *
 * Examples:
 *   "?"               vs "i64"            -> "i64"
 *   "[?]"             vs "[string]"       -> "string"
 *   "[[?]]"           vs "[[i64]]"        -> "i64"
 *   "[map[string:?]]" vs "[map[string:i64]]" -> "i64"
 *   "map[string:[?]]" vs "map[string:[i64]]" -> "i64"
 *   "map[?:?]"        vs "map[i64:i64]"   -> "i64"    (K==V required)
 */
static char *bind_wildcard_string(const char *parameter_type_name, const char *argument_type_name) {
    if (!parameter_type_name || !argument_type_name) return NULL;

    if (strcmp(parameter_type_name, "?") == 0) {
        if (strcmp(argument_type_name, "unknown") == 0) return NULL;
        return strdup(argument_type_name);
    }

    size_t parameter_type_length = strlen(parameter_type_name);
    size_t argument_type_length = strlen(argument_type_name);

    /* Array: both must start/end with brackets; recurse into element types */
    if (parameter_type_name[0] == '[' && argument_type_name[0] == '[') {
        if (parameter_type_length < 3 || argument_type_length < 3) return NULL;
        if (parameter_type_name[parameter_type_length - 1] != ']' || argument_type_name[argument_type_length - 1] != ']') return NULL;
        char *inner_cursor = gray_strndup(parameter_type_name + 1, parameter_type_length - 2);
        char *left_inner = gray_strndup(argument_type_name + 1, argument_type_length - 2);
        char *result = bind_wildcard_string(inner_cursor, left_inner);
        free(inner_cursor);
        free(left_inner);
        return result;
    }

    /* Map: both must be map types; recurse into whichever slot carries '?' */
    if (strncmp(parameter_type_name, "map[", 4) == 0 && strncmp(argument_type_name, "map[", 4) == 0) {
        const char *parameter_key, *parameter_value, *argument_key, *argument_value;
        size_t parameter_key_length, parameter_value_length, argument_key_length, argument_value_length;
        if (!parse_map_key_value(parameter_type_name, &parameter_key, &parameter_key_length, &parameter_value, &parameter_value_length)) return NULL;
        if (!parse_map_key_value(argument_type_name,   &argument_key, &argument_key_length, &argument_value, &argument_value_length)) return NULL;

        bool parameter_key_has_wildcard = false;
        for (size_t i = 0; i < parameter_key_length; i++) if (parameter_key[i] == '?') { parameter_key_has_wildcard = true; break; }
        bool parameter_value_has_wildcard = false;
        for (size_t i = 0; i < parameter_value_length; i++) if (parameter_value[i] == '?') { parameter_value_has_wildcard = true; break; }

        if (!parameter_key_has_wildcard && !parameter_value_has_wildcard) return NULL;

        /* Concrete slots must match the argument's corresponding slot exactly */
        if (!parameter_key_has_wildcard && (argument_key_length != parameter_key_length || memcmp(argument_key, parameter_key, parameter_key_length) != 0)) return NULL;
        if (!parameter_value_has_wildcard && (argument_value_length != parameter_value_length || memcmp(argument_value, parameter_value, parameter_value_length) != 0)) return NULL;

        if (parameter_key_has_wildcard && parameter_value_has_wildcard) {
            /* A single '?' binding must satisfy both slots: require arg K == V */
            if (argument_key_length != argument_value_length || memcmp(argument_key, argument_value, argument_key_length) != 0) return NULL;
        }

        char *result;
        if (parameter_key_has_wildcard) {
            char *cursor = gray_strndup(parameter_key, parameter_key_length);
            char *after_wildcard = gray_strndup(argument_key, argument_key_length);
            result = bind_wildcard_string(cursor, after_wildcard);
            free(cursor); free(after_wildcard);
        } else {
            char *cursor = gray_strndup(parameter_value, parameter_value_length);
            char *after_wildcard = gray_strndup(argument_value, argument_value_length);
            result = bind_wildcard_string(cursor, after_wildcard);
            free(cursor); free(after_wildcard);
        }
        return result;
    }

    return NULL;
}

/* Derive the concrete type that '?' binds to given the parameter's type
 * string and the resolved argument GrayType. Delegates to bind_wildcard_string
 * so composite nesting (arrays-of-arrays, maps-of-arrays, etc.) is handled
 * recursively. Caller owns the returned string. */
static char *bind_wildcard(const char *parameter_type_name, GrayType *argument_type) {
    if (!parameter_type_name || !argument_type) return NULL;
    return bind_wildcard_string(parameter_type_name, type_name(argument_type));
}

/* Mark a just-registered FunctionSignature as generic if any of the declared
 * parameter or return type strings on `decl` contains a '?'. Stores
 * `decl` on the sig so later call-site instantiation can walk the
 * original type_name strings for substitution. */
static void finalize_generic_signature(FunctionSignature *function_signature, AstNode *declaration) {
    function_signature->declaration = declaration;
    if (!declaration || declaration->kind != NODE_FUNCTION_DECLARATION) return;
    for (int i = 0; i < declaration->data.function_declaration.parameter_count; i++) {
        if (type_name_has_wildcard(declaration->data.function_declaration.parameters[i].type_name)) {
            function_signature->is_generic = true;
            return;
        }
    }
    for (int i = 0; i < declaration->data.function_declaration.return_type_count; i++) {
        if (type_name_has_wildcard(declaration->data.function_declaration.return_types[i])) {
            function_signature->is_generic = true;
            return;
        }
    }
}

/* Record a concrete instantiation of a generic function. Returns true
 * if this is a new instantiation (i.e. codegen hasn't seen it yet),
 * false if the same concrete binding was already recorded. Also
 * mirrors the entry onto the source AST func_decl so codegen can
 * enumerate instantiations without needing the FunctionSignature table. */
static bool record_instantiation(FunctionSignature *function_signature, const char *concrete,
                                  AstNode *call_site) {
    if (!function_signature || !concrete) return false;
    /* reject "unknown" as a concrete binding. This comes from
     * the main-pass walk of a generic body where the inner call's
     * arguments are still `?` (TYPE_KIND_UNKNOWN). The real bindings are
     * recorded during the slice-4 re-check pass once the outer
     * function's parameters are rebound to concrete types. */
    if (strcmp(concrete, "unknown") == 0 || strcmp(concrete, "?") == 0) return false;
    for (int i = 0; i < function_signature->instantiation_count; i++) {
        if (strcmp(function_signature->instantiations[i], concrete) == 0) return false;
    }
    if (function_signature->instantiation_count >= function_signature->instantiation_capacity) {
        function_signature->instantiation_capacity = function_signature->instantiation_capacity ? function_signature->instantiation_capacity * 2 : 4;
        function_signature->instantiations = xrealloc(function_signature->instantiations,
            sizeof(const char *) * function_signature->instantiation_capacity);
        function_signature->instantiation_calls = xrealloc(function_signature->instantiation_calls,
            sizeof(AstNode *) * function_signature->instantiation_capacity);
    }
    char *stored = strdup(concrete);
    function_signature->instantiations[function_signature->instantiation_count] = stored;
    function_signature->instantiation_calls[function_signature->instantiation_count] = call_site;
    function_signature->instantiation_count++;

    if (function_signature->declaration && function_signature->declaration->kind == NODE_FUNCTION_DECLARATION) {
        int instantiation_count = function_signature->declaration->data.function_declaration.instantiation_count;
        function_signature->declaration->data.function_declaration.instantiations = xrealloc(
            (void *)function_signature->declaration->data.function_declaration.instantiations,
            sizeof(const char *) * (size_t)(instantiation_count + 1));
        function_signature->declaration->data.function_declaration.instantiations[instantiation_count] = stored;
        function_signature->declaration->data.function_declaration.instantiation_count = instantiation_count + 1;
    }
    return true;
}


static FunctionSignature *find_function(TypeChecker *checker, const char *name) {
    DeclarationEntry *entry = checker_resolve_entry(checker, name);
    if (!entry) entry = module_table_find_mangled(checker->modules, name);
    if (entry && entry->kind == DECLARATION_FUNCTION && entry->registry_index >= 0 &&
        entry->registry_index < checker->function_count)
        return &checker->functions[entry->registry_index];
    return NULL;
}

/* The flat-registry key for the member `name` of module `mod`, written into
 * `buf`. Derived from the declaration the symbol table resolves to, so the
 * module name comes from where the declaration actually lives rather than
 * from the spelling of the reference.
 *
 * Transitional: the stdlib keeps its own registries and is not in the table,
 * so a module the table does not hold still falls back to the string form.
 * The registries remain the authority on what a key names — this decides only
 * how the key is spelled. */
static const char *module_member_key(TypeChecker *checker, const char *module_name,
                                     const char *name, char *buffer, size_t buffer_length) {
    ResolveScope scope = checker_scope(checker);
    DeclarationEntry *entry = module_resolve_qualified(checker->modules, &scope, module_name, name, NULL);
    if (entry) return module_mangle_into(entry, buffer, buffer_length);
    snprintf(buffer, buffer_length, "%s_%s",
             module_table_resolve_alias(checker->modules, module_name), name);
    return buffer;
}

/* The signature of `mod.name`, or NULL. */
static FunctionSignature *find_module_function(TypeChecker *checker, const char *module_name,
                                 const char *name) {
    char lookup_key[MESSAGE_BUFFER_SIZE];
    return find_function(checker, module_member_key(checker, module_name, name, lookup_key, sizeof(lookup_key)));
}

/* The user-defined function a call targets, or NULL (builtins and stdlib
 * keep their own registries and are not in the FunctionSignature table). */
static FunctionSignature *resolve_call_signature(TypeChecker *checker, AstNode *call) {
    if (!call || call->kind != NODE_CALL_EXPRESSION) return NULL;
    AstNode *function_node = call->data.call.function;
    if (!function_node) return NULL;
    if (function_node->kind == NODE_LABEL) {
        FunctionSignature *direct = find_function(checker, function_node->data.label.value);
        if (direct) return direct;
        /* A call through a func-ref variable (`const f = ()target; f(...)`,
         * or `ref(target)`) dispatches to `target`, not to a function named
         * "f" — resolve through Symbol.function_reference_name so the escape and @mem
         * summaries still apply across the indirection. A func-ref call
         * passes its arguments 1:1 (no implicit receiver is inserted), so
         * the resolved callee's param indices line up with this call's
         * arg indices exactly as they would for a direct call. */
        Symbol *symbol = scope_lookup(checker->current_scope, function_node->data.label.value);
        if (symbol && symbol->function_reference_name)
            return find_function(checker, symbol->function_reference_name);
        return NULL;
    }
    if (function_node->kind == NODE_MEMBER_EXPRESSION &&
        function_node->data.member.object &&
        function_node->data.member.object->kind == NODE_LABEL)
        return find_module_function(checker, function_node->data.member.object->data.label.value,
                                function_node->data.member.member);
    return NULL;
}

static unsigned long long returns_parameter_address_of(TypeChecker *checker, FunctionSignature *function_signature);
static void ensure_escape_summary(TypeChecker *checker, FunctionSignature *function_signature);
static Symbol *checker_lookup_symbol(TypeChecker *checker, const char *name);
static Symbol *target_root_symbol(TypeChecker *checker, AstNode *target);
static AstNode *target_root_module_reference(TypeChecker *checker, AstNode *target);
static bool report_write_to_module_variable(TypeChecker *checker, AstNode *report_node, AstNode *place);
static void report_write_to_module_constant(TypeChecker *checker, AstNode *report_node,
                                            AstNode *container, const char *kind);
static const char *target_root_display(TypeChecker *checker, AstNode *target);

/* The value a local named `name` was declared with, searched anywhere in
 * `node`, or NULL. Lets the param-bit walk follow `mut b = Box{p: q};
 * return b`. Local declarations form a DAG (Grayscale forbids forward
 * references), so following initialisers terminates. */
static AstNode *local_initializer(AstNode *node, const char *name) {
    if (!node || !name) return NULL;
    switch (node->kind) {
    case NODE_VARIABLE_DECLARATION:
        if (node->data.variable_declaration.name &&
            strcmp(node->data.variable_declaration.name, name) == 0)
            return node->data.variable_declaration.value;
        return local_initializer(node->data.variable_declaration.value, name);
    case NODE_BLOCK_STATEMENT:
        for (int i = 0; i < node->data.block.count; i++) {
            AstNode *root = local_initializer(node->data.block.statements[i], name);
            if (root) return root;
        }
        return NULL;
    case NODE_IF_STATEMENT: {
        AstNode *root = local_initializer(node->data.if_statement.consequence, name);
        return root ? root : local_initializer(node->data.if_statement.alternative, name);
    }
    case NODE_WHEN_STATEMENT: {
        for (int i = 0; i < node->data.when_statement.case_count; i++) {
            AstNode *root = local_initializer(node->data.when_statement.cases[i].body, name);
            if (root) return root;
        }
        return local_initializer(node->data.when_statement.default_body, name);
    }
    case NODE_FOR_STATEMENT:      return local_initializer(node->data.for_statement.body, name);
    case NODE_FOR_EACH_STATEMENT: return local_initializer(node->data.for_each.body, name);
    case NODE_WHILE_STATEMENT:    return local_initializer(node->data.while_statement.body, name);
    case NODE_LOOP_STATEMENT:     return local_initializer(node->data.loop_statement.body, name);
    default:                 return NULL;
    }
}

/* The function a func-ref initializer names — `()target` or `ref(target)` —
 * or NULL if `value` is neither. */
static const char *function_reference_target_name(AstNode *value) {
    if (!value) return NULL;
    if (value->kind == NODE_FUNCTION_REFERENCE) {
        AstNode *target = value->data.function_reference.function;
        return (target && target->kind == NODE_LABEL) ? target->data.label.value : NULL;
    }
    if (value->kind == NODE_CALL_EXPRESSION && value->data.call.function &&
        value->data.call.function->kind == NODE_LABEL &&
        strcmp(value->data.call.function->data.label.value, "ref") == 0 &&
        value->data.call.argument_count == 1 &&
        value->data.call.arguments[0]->kind == NODE_LABEL)
        return value->data.call.arguments[0]->data.label.value;
    return NULL;
}

/* resolve_call_signature(), extended to see through a call to a func-ref variable
 * declared inside `body` — `const f = ()target; f(...)` or `const f =
 * ref(target); f(...)`. resolve_call_signature()'s own func-ref branch depends on
 * a live checker->current_scope, which the structural summary walks
 * (escape_walk, return_expression_parameter_bits, pointer_checker_mem_walk) never set: they run
 * detached from scope by design, over whichever function's AST they were
 * asked to summarise, which is routinely a different function from whatever
 * is actually being type-checked at the moment the summary is first
 * requested. `body` — the summarised function's own body, which every one
 * of those walks already has on hand — lets local_initializer() recover the
 * same answer structurally, the same way it already recovers a local
 * variable's initializer for this walk without touching scope. */
static FunctionSignature *resolve_call_signature_in_body(TypeChecker *checker, AstNode *body,
                                         AstNode *call) {
    FunctionSignature *direct = resolve_call_signature(checker, call);
    if (direct) return direct;
    AstNode *function_node = call->data.call.function;
    if (!function_node || function_node->kind != NODE_LABEL) return NULL;
    const char *target = function_reference_target_name(
        local_initializer(body, function_node->data.label.value));
    return target ? find_function(checker, target) : NULL;
}

/* True if `node` constructs a tagged-enum variant — `Enum.Variant(args)` or
 * the implicit-selector form `.Variant(args)` — rather than calling a real
 * function. Both compile to a NODE_CALL_EXPRESSION whose function resolves to no
 * FunctionSignature, so origin tracking (return_expression_parameter_bits, container_literal_
 * origin) must recognize the shape directly, the same way it already walks
 * into a struct/array/map literal, or an addr(local) buried in the payload
 * escapes undetected (a tagged-enum return/store is a value carrier exactly
 * like those literals). */
static bool is_tagged_enum_variant_call(TypeChecker *checker, AstNode *node) {
    if (!node || node->kind != NODE_CALL_EXPRESSION) return false;
    AstNode *function_node = node->data.call.function;
    if (!function_node) return false;
    if (function_node->kind == NODE_IMPLICIT_ENUM) return true;
    const char *qualifier = ast_member_qualifier(function_node);
    return qualifier && is_enum_name(checker, resolve_type_alias(checker, qualifier));
}

/* Structural: bitmask of `fs`'s parameters whose address `node` may carry —
 * the parameter named directly, addr()/raw() of a parameter's pointee, a
 * field/element read through a parameter, a value buried in a struct or
 * array literal, a local initialised from any of those, or a value
 * forwarded through another summarised call. Runs while the summary is
 * being built, so it looks only at the AST, never at scope.
 *
 * A bare `p^` yields the pointee *value*, so it carries nothing; `p^.field`
 * reaches into the pointee and can. */
static unsigned long long return_expression_parameter_bits(TypeChecker *checker,
                                                 FunctionSignature *function_signature, AstNode *node) {
    if (!node || !function_signature->declaration) return 0;
    switch (node->kind) {
    case NODE_LABEL: {
        int parameter_count = function_signature->declaration->data.function_declaration.parameter_count;
        for (int i = 0; i < parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
            const char *parameter_name = function_signature->declaration->data.function_declaration.parameters[i].name;
            if (parameter_name && strcmp(parameter_name, node->data.label.value) == 0)
                return 1ull << i;
        }
        AstNode *initializer = local_initializer(function_signature->declaration->data.function_declaration.body,
                                          node->data.label.value);
        if (initializer && initializer != node)
            return return_expression_parameter_bits(checker, function_signature, initializer);
        return 0;
    }
    case NODE_MEMBER_EXPRESSION: {
        AstNode *operand = node->data.member.object;
        while (operand && operand->kind == NODE_POSTFIX_EXPRESSION &&
               operand->data.postfix.operator == TOKEN_CARET)
            operand = operand->data.postfix.left;
        return return_expression_parameter_bits(checker, function_signature, operand);
    }
    case NODE_INDEX_EXPRESSION: {
        AstNode *left_operand = node->data.index_expression.left;
        while (left_operand && left_operand->kind == NODE_POSTFIX_EXPRESSION &&
               left_operand->data.postfix.operator == TOKEN_CARET)
            left_operand = left_operand->data.postfix.left;
        return return_expression_parameter_bits(checker, function_signature, left_operand);
    }
    case NODE_POSTFIX_EXPRESSION:
        if (node->data.postfix.operator == TOKEN_CARET) return 0;
        return return_expression_parameter_bits(checker, function_signature, node->data.postfix.left);
    case NODE_STRUCT_VALUE: {
        unsigned long long bits = 0;
        for (int i = 0; i < node->data.struct_value.count; i++)
            bits |= return_expression_parameter_bits(checker, function_signature,
                                          node->data.struct_value.field_values[i]);
        return bits;
    }
    case NODE_ARRAY_VALUE: {
        unsigned long long bits = 0;
        for (int i = 0; i < node->data.array_value.count; i++)
            bits |= return_expression_parameter_bits(checker, function_signature,
                                          node->data.array_value.elements[i]);
        return bits;
    }
    case NODE_MAP_VALUE: {
        unsigned long long bits = 0;
        for (int i = 0; i < node->data.map_value.count; i++) {
            bits |= return_expression_parameter_bits(checker, function_signature, node->data.map_value.keys[i]);
            bits |= return_expression_parameter_bits(checker, function_signature, node->data.map_value.values[i]);
        }
        return bits;
    }
    case NODE_CALL_EXPRESSION: {
        AstNode *field_expression = node->data.call.function;
        if (field_expression && field_expression->kind == NODE_LABEL && node->data.call.argument_count == 1 &&
            (strcmp(field_expression->data.label.value, "addr") == 0 ||
             strcmp(field_expression->data.label.value, "raw") == 0 ||
             strcmp(field_expression->data.label.value, "copy") == 0))
            return return_expression_parameter_bits(checker, function_signature, node->data.call.arguments[0]);
        if (is_tagged_enum_variant_call(checker, node)) {
            unsigned long long bits = 0;
            for (int i = 0; i < node->data.call.argument_count; i++)
                bits |= return_expression_parameter_bits(checker, function_signature, node->data.call.arguments[i]);
            return bits;
        }
        FunctionSignature *callee = resolve_call_signature_in_body(checker, function_signature->declaration->data.function_declaration.body, node);
        if (callee == function_signature) return 0;
        if (!callee) {
            /* A stdlib module call or bare builtin: no FunctionSignature, so no
             * returns_parameter_address summary to consult — same gap
             * stdlib_call_argument_origin backstops for pointer_origin_of /
             * container_literal_origin, in this function's own bitmask
             * terms. Gated the same way: only when the call's own result
             * could structurally carry a pointer.
             *
             * A summary is computed lazily, on demand from whichever call
             * site first needs it — e.g. from a caller textually earlier in
             * the file, whose own body is what's actively being checked and
             * whose scope is therefore live on checker->current_scope. This
             * walk is structural precisely so it never needs a live scope
             * for *this* function's own body; calling resolve_expression()
             * here would resolve `node` (e.g. a func-typed-parameter call
             * `f(p)`) against the wrong function's scope and misreport `f`
             * and `p` as undefined. type_table_get() is a plain lookup: it
             * returns the type if this exact node was already resolved
             * during a properly-scoped pass over this function's own body,
             * and NULL — a safe "unknown, no bit set" — otherwise. */
            GrayType *return_type = type_table_get(checker->type_table, node);
            if (!return_type || !(return_type->kind == TYPE_KIND_POINTER || return_type->kind == TYPE_KIND_STRUCT ||
                         return_type->kind == TYPE_KIND_ARRAY || return_type->kind == TYPE_KIND_MAP))
                return 0;
            unsigned long long bits = 0;
            for (int i = 0; i < node->data.call.argument_count; i++)
                bits |= return_expression_parameter_bits(checker, function_signature, node->data.call.arguments[i]);
            return bits;
        }
        unsigned long long callee_bits = returns_parameter_address_of(checker, callee);
        unsigned long long bits = 0;
        for (int i = 0; i < callee->parameter_count &&
                        i < node->data.call.argument_count && i < MAX_TRACKED_PARAMETERS; i++)
            if (callee_bits & (1ull << i))
                bits |= return_expression_parameter_bits(checker, function_signature, node->data.call.arguments[i]);
        return bits;
    }
    default:
        return 0;
    }
}

/* OR together the param bits of every `return` reachable in a statement
 * subtree, without descending into a nested function declaration. */
static unsigned long long return_statement_parameter_bits(TypeChecker *checker,
                                                 FunctionSignature *function_signature, AstNode *node) {
    if (!node) return 0;
    unsigned long long bits = 0;
    switch (node->kind) {
    case NODE_RETURN_STATEMENT:
        for (int i = 0; i < node->data.return_statement.count; i++)
            bits |= return_expression_parameter_bits(checker, function_signature,
                                           node->data.return_statement.values[i]);
        break;
    case NODE_BLOCK_STATEMENT:
        for (int i = 0; i < node->data.block.count; i++)
            bits |= return_statement_parameter_bits(checker, function_signature, node->data.block.statements[i]);
        break;
    case NODE_IF_STATEMENT:
        bits |= return_statement_parameter_bits(checker, function_signature, node->data.if_statement.consequence);
        bits |= return_statement_parameter_bits(checker, function_signature, node->data.if_statement.alternative);
        break;
    case NODE_WHEN_STATEMENT:
        for (int i = 0; i < node->data.when_statement.case_count; i++)
            bits |= return_statement_parameter_bits(checker, function_signature,
                                           node->data.when_statement.cases[i].body);
        bits |= return_statement_parameter_bits(checker, function_signature, node->data.when_statement.default_body);
        break;
    case NODE_FOR_STATEMENT:
        bits |= return_statement_parameter_bits(checker, function_signature, node->data.for_statement.body);
        break;
    case NODE_FOR_EACH_STATEMENT:
        bits |= return_statement_parameter_bits(checker, function_signature, node->data.for_each.body);
        break;
    case NODE_WHILE_STATEMENT:
        bits |= return_statement_parameter_bits(checker, function_signature, node->data.while_statement.body);
        break;
    case NODE_LOOP_STATEMENT:
        bits |= return_statement_parameter_bits(checker, function_signature, node->data.loop_statement.body);
        break;
    default:
        break;
    }
    return bits;
}

/* --- parameter_escape_into: where a parameter's address ends up living --- */

/* Root name of an assignment/insert target, seeing *through* a pointer
 * dereference (unlike assignment_target_root_name, which stops at `^`):
 * writing to `dst^.field` stores into the pointee, which for a pointer
 * parameter is the caller's memory. */
static const char *escape_root_name(AstNode *expression) {
    while (expression) {
        switch (expression->kind) {
        case NODE_LABEL:       return expression->data.label.value;
        case NODE_MEMBER_EXPRESSION: expression = expression->data.member.object; break;
        case NODE_INDEX_EXPRESSION:  expression = expression->data.index_expression.left; break;
        case NODE_POSTFIX_EXPRESSION:
            if (expression->data.postfix.operator != TOKEN_CARET) return NULL;
            expression = expression->data.postfix.left;
            break;
        default: return NULL;
        }
    }
    return NULL;
}

/* Is `name` declared as a local anywhere in `node`? */
static bool declared_in_subtree(AstNode *node, const char *name) {
    if (!node || !name) return false;
    switch (node->kind) {
    case NODE_VARIABLE_DECLARATION:
        if (node->data.variable_declaration.name &&
            strcmp(node->data.variable_declaration.name, name) == 0)
            return true;
        return declared_in_subtree(node->data.variable_declaration.value, name);
    case NODE_BLOCK_STATEMENT:
        for (int i = 0; i < node->data.block.count; i++)
            if (declared_in_subtree(node->data.block.statements[i], name)) return true;
        return false;
    case NODE_IF_STATEMENT:
        return declared_in_subtree(node->data.if_statement.consequence, name) ||
               declared_in_subtree(node->data.if_statement.alternative, name);
    case NODE_WHEN_STATEMENT:
        for (int i = 0; i < node->data.when_statement.case_count; i++)
            if (declared_in_subtree(node->data.when_statement.cases[i].body, name)) return true;
        return declared_in_subtree(node->data.when_statement.default_body, name);
    case NODE_FOR_STATEMENT:
        if (node->data.for_statement.variable_name &&
            strcmp(node->data.for_statement.variable_name, name) == 0) return true;
        return declared_in_subtree(node->data.for_statement.body, name);
    case NODE_FOR_EACH_STATEMENT:
        if ((node->data.for_each.variable_name &&
             strcmp(node->data.for_each.variable_name, name) == 0) ||
            (node->data.for_each.index_name &&
             strcmp(node->data.for_each.index_name, name) == 0)) return true;
        return declared_in_subtree(node->data.for_each.body, name);
    case NODE_WHILE_STATEMENT: return declared_in_subtree(node->data.while_statement.body, name);
    case NODE_LOOP_STATEMENT:  return declared_in_subtree(node->data.loop_statement.body, name);
    default: return false;
    }
}

/* Build the set of top-level NODE_VARIABLE_DECLARATION names. The statement list is fixed
 * once checking begins, so this runs once and every later is_module_level_variable()
 * is a hash probe instead of a full-program scan (that scan was O(assignments *
 * declarations) across a file). */
static void build_module_variable_index(TypeChecker *checker) {
    checker->is_module_variable_index_built = true;
    AstNode *program = checker->program;
    if (!program || program->kind != NODE_PROGRAM) return;
    int statement_count = program->data.program.statement_count;

    int variable_count = 0;
    for (int i = 0; i < statement_count; i++) {
        AstNode *statement = program->data.program.statements[i];
        if (statement && statement->kind == NODE_VARIABLE_DECLARATION && statement->data.variable_declaration.name) variable_count++;
    }
    if (variable_count == 0) return;

    int capacity = 16;
    while (capacity < (variable_count + 1) * 2) capacity *= 2;
    checker->module_variable_index_names = xcalloc((size_t)capacity, sizeof(char *));
    checker->module_variable_index_capacity = capacity;

    uint32_t mask = (uint32_t)(capacity - 1);
    for (int i = 0; i < statement_count; i++) {
        AstNode *statement = program->data.program.statements[i];
        if (!statement || statement->kind != NODE_VARIABLE_DECLARATION || !statement->data.variable_declaration.name) continue;
        const char *name = statement->data.variable_declaration.name;
        uint32_t slot = scope_string_hash(name) & mask;
        while (checker->module_variable_index_names[slot]) {
            if (strcmp(checker->module_variable_index_names[slot], name) == 0) break;
            slot = (slot + 1) & mask;
        }
        checker->module_variable_index_names[slot] = name;
    }
}

/* Is `name` a module-level variable of the program being checked? Only
 * returns true when it can prove it, so an unknown name is treated as a
 * local (a conservative miss, never a false E3163). */
static bool is_module_level_variable(TypeChecker *checker, const char *name) {
    if (!checker->program || !name ||
        checker->program->kind != NODE_PROGRAM) return false;
    if (!checker->is_module_variable_index_built) build_module_variable_index(checker);
    if (!checker->module_variable_index_names) return false;
    uint32_t mask = (uint32_t)(checker->module_variable_index_capacity - 1);
    uint32_t slot = scope_string_hash(name) & mask;
    while (checker->module_variable_index_names[slot]) {
        if (strcmp(checker->module_variable_index_names[slot], name) == 0) return true;
        slot = (slot + 1) & mask;
    }
    return false;
}

/* Classify a store target's root: a parameter index, PARAMETER_ESCAPE_GLOBAL, or
 * PARAMETER_ESCAPE_NONE (a local — an in-function concern the direct E3163
 * checks already cover). */
static signed char escape_destination_for_root(TypeChecker *checker, FunctionSignature *function_signature,
                                        const char *root, AstNode *body) {
    if (!root) return PARAMETER_ESCAPE_NONE;
    int parameter_count = function_signature->declaration->data.function_declaration.parameter_count;
    for (int i = 0; i < parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
        const char *parameter_name = function_signature->declaration->data.function_declaration.parameters[i].name;
        if (parameter_name && strcmp(parameter_name, root) == 0) return (signed char)i;
    }
    if (declared_in_subtree(body, root)) return PARAMETER_ESCAPE_NONE;
    if (is_module_level_variable(checker, root)) return PARAMETER_ESCAPE_GLOBAL;
    return PARAMETER_ESCAPE_NONE;
}

/* stdlib functions that store an argument into a container argument. */
typedef struct {
    const char *module_name;
    const char *function_name;
    int value_argument;
    int container_argument;
} ContainerSink;

static const ContainerSink container_sinks[] = {
    {"arrays", "append",    1, 0},
    {"arrays", "prepend",   1, 0},
    {"arrays", "insert_at", 2, 0},
    {"arrays", "fill",      2, 0},
};

static const ContainerSink *find_container_sink(TypeChecker *checker, AstNode *call) {
    AstNode *function_node = call->data.call.function;
    if (!function_node || function_node->kind != NODE_MEMBER_EXPRESSION) return NULL;
    const char *qualifier = ast_member_qualifier(function_node);
    if (!qualifier) return NULL;
    const char *module_name = typechecker_resolve_alias(checker, qualifier);
    const char *member_function_name = function_node->data.member.member;
    if (!module_name || !member_function_name) return NULL;
    for (size_t i = 0; i < sizeof container_sinks / sizeof container_sinks[0]; i++)
        if (strcmp(container_sinks[i].module_name, module_name) == 0 &&
            strcmp(container_sinks[i].function_name, member_function_name) == 0)
            return &container_sinks[i];
    return NULL;
}

static void record_parameter_escape(FunctionSignature *function_signature, unsigned long long bits,
                                signed char destination, const char *global_name) {
    for (int i = 0; i < function_signature->parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
        if (!(bits & (1ull << i))) continue;
        if (function_signature->parameter_escape_into[i] == PARAMETER_ESCAPE_NONE ||
            destination == PARAMETER_ESCAPE_GLOBAL) {
            function_signature->parameter_escape_into[i] = destination;
            if (destination == PARAMETER_ESCAPE_GLOBAL)
                function_signature->parameter_escape_global_name[i] = global_name;
        }
        function_signature->parameter_escape_via_function[i] = -1;
    }
}

/* record_parameter_escape() for an argument forwarded through an indirect call
 * via func-typed parameter `func_param`, at argument position `pos`. The
 * escape stays attributable to that one call only while nothing else has
 * escaped the parameter (parameter_escape_via_function). */
static void record_parameter_escape_via_function(FunctionSignature *function_signature, unsigned long long bits,
                                         int function_parameter, int position) {
    for (int i = 0; i < function_signature->parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
        if (!(bits & (1ull << i))) continue;
        if (function_signature->parameter_escape_into[i] == PARAMETER_ESCAPE_NONE) {
            function_signature->parameter_escape_into[i] = PARAMETER_ESCAPE_GLOBAL;
            function_signature->parameter_escape_via_function[i] = function_parameter;
            function_signature->parameter_escape_via_position[i] = position;
        } else if (function_signature->parameter_escape_into[i] != PARAMETER_ESCAPE_GLOBAL ||
                   function_signature->parameter_escape_via_function[i] != function_parameter ||
                   function_signature->parameter_escape_via_position[i] != position) {
            function_signature->parameter_escape_into[i] = PARAMETER_ESCAPE_GLOBAL;
            function_signature->parameter_escape_via_function[i] = -1;
        }
    }
}

/* Index of the `fs` parameter that `call`'s target names, when that parameter
 * is function-typed — an indirect call whose real callee is not statically
 * known. Escape analysis cannot see into it, so every argument such a call
 * receives is treated as escaping to an unknown, program-lifetime sink
 * (#2692), until a call site supplies a known function for it. -1 otherwise. */
static int call_function_typed_parameter_index(FunctionSignature *function_signature, AstNode *call) {
    AstNode *function_node = call->data.call.function;
    if (!function_node || function_node->kind != NODE_LABEL || !function_signature->declaration) return -1;
    int parameter_count = function_signature->declaration->data.function_declaration.parameter_count;
    for (int i = 0; i < parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
        const Parameter *parameter = &function_signature->declaration->data.function_declaration.parameters[i];
        if (parameter->name && strcmp(parameter->name, function_node->data.label.value) == 0)
            return parameter->type_name && strncmp(parameter->type_name, "func(", 5) == 0 ? i : -1;
    }
    return -1;
}

/* True when a call's target is a func *value* that cannot be pinned to one
 * declaration — a func read from an array/map element (`arr[i](...)`), or one
 * of `fs`'s own func-typed parameters. Structural (no live scope), for the
 * summary walks. Such a call may forward any pointer argument anywhere
 * (#2661). */
static bool call_target_is_opaque_function(FunctionSignature *function_signature, AstNode *call) {
    AstNode *function_node = call->data.call.function;
    if (function_node && function_node->kind == NODE_INDEX_EXPRESSION) return true;
    return call_function_typed_parameter_index(function_signature, call) >= 0;
}

/* Is `name` a module-level const-declared variable of the program being
 * checked? */
static bool is_module_level_const(TypeChecker *checker, const char *name) {
    AstNode *program = checker->program;
    if (!program || program->kind != NODE_PROGRAM || !name) return false;
    for (int i = 0; i < program->data.program.statement_count; i++) {
        AstNode *statement = program->data.program.statements[i];
        if (statement && statement->kind == NODE_VARIABLE_DECLARATION && !statement->data.variable_declaration.is_mutable &&
            statement->data.variable_declaration.name && strcmp(statement->data.variable_declaration.name, name) == 0)
            return true;
    }
    return false;
}

/* Structural: does a value `fs` returns point at a module-level const-declared
 * variable — `addr(GLOBAL)`, a local initialised from one, or the result of
 * another function that returns one. */
static bool return_expression_points_to_const(TypeChecker *checker, FunctionSignature *function_signature,
                                        AstNode *body, AstNode *expression) {
    if (!expression) return false;
    if (expression->kind == NODE_LABEL) {
        AstNode *initializer = local_initializer(body, expression->data.label.value);
        return initializer && initializer != expression && return_expression_points_to_const(checker, function_signature, body, initializer);
    }
    /* A struct, array or map literal, or a tagged-enum variant, that holds
     * such a pointer carries it out of the function. */
    if (expression->kind == NODE_STRUCT_VALUE) {
        for (int i = 0; i < expression->data.struct_value.count; i++)
            if (return_expression_points_to_const(checker, function_signature, body, expression->data.struct_value.field_values[i]))
                return true;
        return false;
    }
    if (expression->kind == NODE_ARRAY_VALUE) {
        for (int i = 0; i < expression->data.array_value.count; i++)
            if (return_expression_points_to_const(checker, function_signature, body, expression->data.array_value.elements[i]))
                return true;
        return false;
    }
    if (expression->kind == NODE_MAP_VALUE) {
        for (int i = 0; i < expression->data.map_value.count; i++)
            if (return_expression_points_to_const(checker, function_signature, body, expression->data.map_value.values[i]))
                return true;
        return false;
    }
    if (expression->kind != NODE_CALL_EXPRESSION) return false;
    if (is_tagged_enum_variant_call(checker, expression)) {
        for (int i = 0; i < expression->data.call.argument_count; i++)
            if (return_expression_points_to_const(checker, function_signature, body, expression->data.call.arguments[i]))
                return true;
        return false;
    }
    AstNode *field_expression = expression->data.call.function;
    if (field_expression && field_expression->kind == NODE_LABEL && expression->data.call.argument_count == 1) {
        if (strcmp(field_expression->data.label.value, "addr") == 0) {
            const char *root = assignment_target_root_name(expression->data.call.arguments[0]);
            if (!root || declared_in_subtree(body, root)) return false;
            int parameter_count = function_signature->declaration->data.function_declaration.parameter_count;
            for (int i = 0; i < parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
                const char *parameter_name = function_signature->declaration->data.function_declaration.parameters[i].name;
                if (parameter_name && strcmp(parameter_name, root) == 0) return false;
            }
            return is_module_level_const(checker, root);
        }
        if (strcmp(field_expression->data.label.value, "copy") == 0)
            return return_expression_points_to_const(checker, function_signature, body, expression->data.call.arguments[0]);
    }
    FunctionSignature *callee = resolve_call_signature_in_body(checker, body, expression);
    if (!callee || callee == function_signature) return false;
    ensure_escape_summary(checker, callee);
    return callee->can_return_const_pointer;
}

/* Bit of the pointer parameter of `fs` that a write rooted at `root` lands
 * in: `root` names the parameter itself, or a local declared as a plain copy
 * of it (`mut q = p`). 0 for anything else, including a by-value parameter. */
static unsigned long long pointer_parameter_bit_for_root(FunctionSignature *function_signature, AstNode *body,
                                                     const char *root) {
    for (int hop_count = 0; root && hop_count < MAX_TRACKED_PARAMETERS; hop_count++) {
        int parameter_count = function_signature->declaration->data.function_declaration.parameter_count;
        for (int i = 0; i < parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
            const Parameter *parameter = &function_signature->declaration->data.function_declaration.parameters[i];
            if (parameter->name && strcmp(parameter->name, root) == 0)
                return parameter->type_name && parameter->type_name[0] == '^' ? 1ull << i : 0;
        }
        AstNode *initializer = local_initializer(body, root);
        root = initializer && initializer->kind == NODE_LABEL ? initializer->data.label.value : NULL;
    }
    return 0;
}

/* Bit of the pointer parameter that assigning to `target` writes through —
 * a `p^`, `p^.f`, `p.f` or `p^[i]` target, never the bare `p = ...`, which
 * only repoints the parameter. */
static unsigned long long write_target_parameter_bit(FunctionSignature *function_signature, AstNode *body,
                                                 AstNode *target) {
    if (!target || target->kind == NODE_LABEL) return 0;
    return pointer_parameter_bit_for_root(function_signature, body, escape_root_name(target));
}

/* Bit of the pointer parameter that a callee writing through the argument
 * `arg` reaches: the parameter itself (`f(p)`), or the place `addr(p^.f)`
 * takes the address of. */
static unsigned long long pointer_argument_parameter_bit(FunctionSignature *function_signature, AstNode *body,
                                                AstNode *argument) {
    if (!argument) return 0;
    if (argument->kind == NODE_LABEL)
        return pointer_parameter_bit_for_root(function_signature, body, argument->data.label.value);
    if (argument->kind == NODE_CALL_EXPRESSION && argument->data.call.function &&
        argument->data.call.function->kind == NODE_LABEL &&
        strcmp(argument->data.call.function->data.label.value, "addr") == 0 &&
        argument->data.call.argument_count == 1)
        return write_target_parameter_bit(function_signature, body, argument->data.call.arguments[0]);
    return 0;
}

/* Bit of the pointer parameter that instance dispatch `p.f()` (or `p^.f()`)
 * writes through, for a call dispatch has not rewritten yet — a function
 * summarised before its own body is checked still sees the instance form, not
 * `Type.f(p)`. The struct function must write through its receiver: a `^T`
 * one that writes through it, or a `&` one, which takes it by reference. */
static unsigned long long dispatch_receiver_write_bit(TypeChecker *checker,
                                                      FunctionSignature *function_signature, AstNode *body,
                                                      AstNode *call) {
    AstNode *function_node = call->data.call.function;
    if (!function_node || function_node->kind != NODE_MEMBER_EXPRESSION) return 0;
    AstNode *object = function_node->data.member.object;
    if (object && object->kind == NODE_POSTFIX_EXPRESSION && object->data.postfix.operator == TOKEN_CARET)
        object = object->data.postfix.left;
    if (!object || object->kind != NODE_LABEL) return 0;
    unsigned long long write_bit = pointer_parameter_bit_for_root(function_signature, body, object->data.label.value);
    if (!write_bit) return 0;
    int parameter_index = 0;
    while (!((write_bit >> parameter_index) & 1)) parameter_index++;
    GrayType *parameter_type = parameter_index < function_signature->parameter_count ? function_signature->parameter_types[parameter_index] : NULL;
    if (!parameter_type || parameter_type->kind != TYPE_KIND_POINTER || !parameter_type->element_type) return 0;
    char lookup_key[MESSAGE_BUFFER_SIZE], struct_function_key[MESSAGE_BUFFER_SIZE];
    snprintf(struct_function_key, sizeof(struct_function_key), "%s_%s",
        checker_resolve_declaration_into(checker, parameter_type->element_type, lookup_key, sizeof(lookup_key)),
        function_node->data.member.member);
    FunctionSignature *callee = find_function(checker, struct_function_key);
    if (!callee || !callee->declaration || callee->declaration->kind != NODE_FUNCTION_DECLARATION ||
        callee->declaration->data.function_declaration.parameter_count == 0)
        return 0;
    ensure_escape_summary(checker, callee);
    bool writes = (callee->writes_through_parameter & 1) ||
                  callee->declaration->data.function_declaration.parameters[0].is_mutable;
    return writes ? write_bit : 0;
}

/* Scan a function body for places a parameter's address is stored into
 * caller-visible memory: an assignment whose target roots at another
 * parameter or a module-level variable, a stdlib container insert, or a
 * call that itself escapes the argument. */
static void escape_walk(TypeChecker *checker, FunctionSignature *function_signature, AstNode *body,
                        AstNode *node) {
    if (!node) return;
    switch (node->kind) {
    case NODE_ASSIGN_STATEMENT: {
        function_signature->writes_through_parameter |=
            write_target_parameter_bit(function_signature, body, node->data.assign.target);
        const char *target_root = escape_root_name(node->data.assign.target);
        signed char destination = escape_destination_for_root(checker, function_signature, target_root, body);
        if (destination != PARAMETER_ESCAPE_NONE)
            record_parameter_escape(function_signature, return_expression_parameter_bits(checker, function_signature,
                node->data.assign.value), destination,
                destination == PARAMETER_ESCAPE_GLOBAL ? target_root : NULL);
        escape_walk(checker, function_signature, body, node->data.assign.value);
        break;
    }
    case NODE_CALL_EXPRESSION: {
        const ContainerSink *sink = find_container_sink(checker, node);
        if (sink && node->data.call.argument_count > sink->value_argument &&
            node->data.call.argument_count > sink->container_argument) {
            const char *container_root =
                escape_root_name(node->data.call.arguments[sink->container_argument]);
            signed char destination = escape_destination_for_root(checker, function_signature, container_root, body);
            if (destination != PARAMETER_ESCAPE_NONE)
                record_parameter_escape(function_signature, return_expression_parameter_bits(checker, function_signature,
                    node->data.call.arguments[sink->value_argument]), destination,
                    destination == PARAMETER_ESCAPE_GLOBAL ? container_root : NULL);
        }
        /* passes_parameter_to_extern (#2732): a parameter's address reaching an
         * extern.func() call directly, right here in this function's own
         * body — the callee-side half of the E3154 stack-address-to-C
         * guard, computed structurally alongside the rest of this summary
         * the same way returns_parameter_address is. */
        AstNode *function_node = node->data.call.function;
        if (function_node && function_node->kind == NODE_MEMBER_EXPRESSION && ast_member_qualifier(function_node) &&
            strcmp(ast_member_qualifier(function_node), "extern") == 0) {
            for (int i = 0; i < node->data.call.argument_count && i < MAX_TRACKED_PARAMETERS; i++)
                function_signature->passes_parameter_to_extern |= return_expression_parameter_bits(checker, function_signature,
                    node->data.call.arguments[i]);
        }
        FunctionSignature *callee = resolve_call_signature_in_body(checker, body, node);
        if (!callee)
            function_signature->writes_through_parameter |= dispatch_receiver_write_bit(checker, function_signature, body, node);
        if (callee && callee != function_signature) {
            ensure_escape_summary(checker, callee);
            for (int index = 0; index < callee->parameter_count &&
                            index < node->data.call.argument_count && index < MAX_TRACKED_PARAMETERS; index++) {
                if ((callee->writes_through_parameter >> index) & 1)
                    function_signature->writes_through_parameter |=
                        pointer_argument_parameter_bit(function_signature, body, node->data.call.arguments[index]);
                if (callee->declaration && callee->declaration->kind == NODE_FUNCTION_DECLARATION &&
                    index < callee->declaration->data.function_declaration.parameter_count &&
                    callee->declaration->data.function_declaration.parameters[index].is_mutable)
                    function_signature->writes_through_parameter |=
                        write_target_parameter_bit(function_signature, body, node->data.call.arguments[index]);
            }
            for (int index = 0; index < callee->parameter_count &&
                            index < node->data.call.argument_count && index < MAX_TRACKED_PARAMETERS; index++) {
                signed char callee_destination = callee->parameter_escape_into[index];
                if (callee_destination == PARAMETER_ESCAPE_NONE) continue;
                unsigned long long bits = return_expression_parameter_bits(checker, function_signature,
                    node->data.call.arguments[index]);
                if (!bits) continue;
                if (callee_destination == PARAMETER_ESCAPE_GLOBAL) {
                    record_parameter_escape(function_signature, bits, PARAMETER_ESCAPE_GLOBAL,
                        callee->parameter_escape_global_name[index]);
                } else if (callee_destination < node->data.call.argument_count) {
                    const char *destination_root =
                        escape_root_name(node->data.call.arguments[callee_destination]);
                    signed char destination = escape_destination_for_root(checker, function_signature, destination_root, body);
                    if (destination != PARAMETER_ESCAPE_NONE)
                        record_parameter_escape(function_signature, bits, destination,
                            destination == PARAMETER_ESCAPE_GLOBAL ? destination_root : NULL);
                }
            }
            /* passes_parameter_to_extern forwards through a call to another
             * summarised function the same way parameter_escape_into does just
             * above: `helper(a) { extern.free(a) }` called as
             * `outer(x) { helper(x) }` makes outer's own parameter 0 reach
             * extern too. */
            for (int index = 0; index < callee->parameter_count &&
                            index < node->data.call.argument_count && index < MAX_TRACKED_PARAMETERS; index++) {
                if (!((callee->passes_parameter_to_extern >> index) & 1)) continue;
                function_signature->passes_parameter_to_extern |= return_expression_parameter_bits(checker, function_signature,
                    node->data.call.arguments[index]);
            }
        } else if (!callee && call_target_is_opaque_function(function_signature, node)) {
            int function_parameter = call_function_typed_parameter_index(function_signature, node);
            for (int i = 0; i < node->data.call.argument_count && i < MAX_TRACKED_PARAMETERS; i++) {
                function_signature->writes_through_parameter |=
                    pointer_argument_parameter_bit(function_signature, body, node->data.call.arguments[i]);
                unsigned long long bits = return_expression_parameter_bits(checker, function_signature,
                    node->data.call.arguments[i]);
                if (function_parameter >= 0)
                    record_parameter_escape_via_function(function_signature, bits, function_parameter, i);
                else
                    record_parameter_escape(function_signature, bits, PARAMETER_ESCAPE_GLOBAL, NULL);
            }
        }
        for (int i = 0; i < node->data.call.argument_count; i++)
            escape_walk(checker, function_signature, body, node->data.call.arguments[i]);
        break;
    }
    case NODE_VARIABLE_DECLARATION:
        escape_walk(checker, function_signature, body, node->data.variable_declaration.value);
        break;
    case NODE_BLOCK_STATEMENT:
        for (int i = 0; i < node->data.block.count; i++)
            escape_walk(checker, function_signature, body, node->data.block.statements[i]);
        break;
    case NODE_IF_STATEMENT:
        escape_walk(checker, function_signature, body, node->data.if_statement.consequence);
        escape_walk(checker, function_signature, body, node->data.if_statement.alternative);
        break;
    case NODE_WHEN_STATEMENT:
        for (int i = 0; i < node->data.when_statement.case_count; i++)
            escape_walk(checker, function_signature, body, node->data.when_statement.cases[i].body);
        escape_walk(checker, function_signature, body, node->data.when_statement.default_body);
        break;
    case NODE_FOR_STATEMENT:
        escape_walk(checker, function_signature, body, node->data.for_statement.body);
        break;
    case NODE_FOR_EACH_STATEMENT:
        escape_walk(checker, function_signature, body, node->data.for_each.body);
        break;
    case NODE_WHILE_STATEMENT:
        escape_walk(checker, function_signature, body, node->data.while_statement.body);
        break;
    case NODE_LOOP_STATEMENT:
        escape_walk(checker, function_signature, body, node->data.loop_statement.body);
        break;
    case NODE_EXPRESSION_STATEMENT:
        escape_walk(checker, function_signature, body, node->data.expression_statement.expression);
        break;
    case NODE_ENSURE_STATEMENT:
        escape_walk(checker, function_signature, body, node->data.ensure_statement.expression);
        break;
    case NODE_RETURN_STATEMENT:
        for (int i = 0; i < node->data.return_statement.count; i++) {
            if (return_expression_points_to_const(checker, function_signature, body,
                                            node->data.return_statement.values[i]))
                function_signature->can_return_const_pointer = true;
            escape_walk(checker, function_signature, body, node->data.return_statement.values[i]);
        }
        break;
    default:
        break;
    }
}

/* Lazily compute and memoise `fs`'s escape summary (returns_parameter_address and
 * parameter_escape_into). A function caught mid-computation (recursion) is left
 * with whatever partial summary it has — conservative, never a false
 * positive. */
static void ensure_escape_summary(TypeChecker *checker, FunctionSignature *function_signature) {
    if (!function_signature || function_signature->escape_state != 0) return;
    function_signature->escape_state = 1;
    function_signature->returns_parameter_address = 0;
    memset(function_signature->parameter_escape_into, PARAMETER_ESCAPE_NONE, sizeof function_signature->parameter_escape_into);
    memset(function_signature->parameter_escape_global_name, 0, sizeof function_signature->parameter_escape_global_name);
    memset(function_signature->parameter_escape_via_function, -1, sizeof function_signature->parameter_escape_via_function);
    function_signature->passes_parameter_to_extern = 0;
    function_signature->writes_through_parameter = 0;
    function_signature->can_return_const_pointer = false;
    AstNode *body = (function_signature->declaration && function_signature->declaration->kind == NODE_FUNCTION_DECLARATION)
                    ? function_signature->declaration->data.function_declaration.body : NULL;
    if (body && function_signature->declaration->data.function_declaration.parameter_count <= 64) {
        /* returns_parameter_address matters only when the return value can carry a
         * pointer: a pointer, or an aggregate that may hold one. A `?` return
         * slot resolves to TYPE_KIND_UNKNOWN here — there is no call-site binding
         * yet to give it a concrete kind — but real call sites bind it to
         * pointer/aggregate types constantly, so check the slot's declared
         * name for a wildcard too; otherwise a wildcard-return function's
         * summary is never computed and forwarding a pointer through it
         * hides the escape from both E3162 and E3163. */
        bool is_escapable_return = false;
        int declared_return_count = function_signature->declaration->data.function_declaration.return_type_count;
        for (int i = 0; i < function_signature->return_count; i++) {
            GrayType *return_type = function_signature->return_types[i];
            if (return_type && (return_type->kind == TYPE_KIND_POINTER || return_type->kind == TYPE_KIND_STRUCT ||
                       return_type->kind == TYPE_KIND_ARRAY || return_type->kind == TYPE_KIND_MAP ||
                       return_type->kind == TYPE_KIND_ENUM))
                is_escapable_return = true;
            else if (i < declared_return_count &&
                     type_name_has_wildcard(function_signature->declaration->data.function_declaration.return_types[i]))
                is_escapable_return = true;
        }
        if (is_escapable_return)
            function_signature->returns_parameter_address = return_statement_parameter_bits(checker, function_signature, body);
        escape_walk(checker, function_signature, body, body);
    }
    function_signature->escape_state = 2;
}

static unsigned long long returns_parameter_address_of(TypeChecker *checker, FunctionSignature *function_signature) {
    if (!function_signature) return 0;
    ensure_escape_summary(checker, function_signature);
    return function_signature->returns_parameter_address;
}

/* --- const-sourced pointers ---
 *
 * A pointer to a const-declared variable is read-only: writing through it is
 * E3122. Symbol.is_const_source marks a variable that holds such a pointer, or
 * an aggregate that holds one in a field or element. It is set from anything
 * that points at a const — addr(const), a marked variable, a field or element
 * of one, a literal built from one, or a call that returns one — not only from
 * a direct `addr(const)` initializer. One flag covers the whole variable, so a
 * struct holding a const pointer and a mutable one is treated as holding
 * const pointers throughout. */

static GrayType *const_walk_expression_type(TypeChecker *checker, AstNode *expression) {
    GrayType *type = type_table_get(checker->type_table, expression);
    if (type) return type;
    if (expression->kind == NODE_LABEL) {
        Symbol *symbol = checker_lookup_symbol(checker, expression->data.label.value);
        return symbol ? symbol->type : NULL;
    }
    return NULL;
}

static bool expression_points_to_const(TypeChecker *checker, AstNode *expression);

/* `^^T`: a pointer to a pointer. A variable of this type marked const_source
 * holds a pointer to a pointer at a const-declared variable, so it is what
 * `pp^` reads, not what `pp^` writes, that reaches the const. */
static bool is_pointer_to_pointer(GrayType *type) {
    return type && type->kind == TYPE_KIND_POINTER && type->element_type && type->element_type[0] == '^';
}

/* The pointer expression that a write through `place` dereferences, when it
 * points at a const-declared variable — `p^`, `p^.f`, `p.f` (auto-deref),
 * `h.p^.f` — else NULL. */
static AstNode *place_derefs_const_pointer(TypeChecker *checker, AstNode *place) {
    AstNode *current = place;
    while (current) {
        AstNode *inner = NULL;
        bool deref = false;
        switch (current->kind) {
        case NODE_POSTFIX_EXPRESSION:
            if (current->data.postfix.operator != TOKEN_CARET) return NULL;
            inner = current->data.postfix.left;
            deref = true;
            break;
        case NODE_MEMBER_EXPRESSION: {
            inner = current->data.member.object;
            GrayType *type = inner ? const_walk_expression_type(checker, inner) : NULL;
            deref = type && type->kind == TYPE_KIND_POINTER;
            break;
        }
        case NODE_INDEX_EXPRESSION:
            inner = current->data.index_expression.left;
            break;
        default:
            return NULL;
        }
        if (!inner) return NULL;
        if (deref && !is_pointer_to_pointer(const_walk_expression_type(checker, inner)) &&
            expression_points_to_const(checker, inner)) return inner;
        current = inner;
    }
    return NULL;
}

static bool expression_points_to_const(TypeChecker *checker, AstNode *expression) {
    if (!expression) return false;
    switch (expression->kind) {
    case NODE_LABEL: {
        Symbol *symbol = checker_lookup_symbol(checker, expression->data.label.value);
        return symbol && symbol->is_const_source;
    }
    case NODE_MEMBER_EXPRESSION:
    case NODE_INDEX_EXPRESSION: {
        /* A field or element of a marked aggregate is marked; one read out of
         * memory behind a pointer is a different pointer. */
        AstNode *inner = expression->kind == NODE_MEMBER_EXPRESSION ? expression->data.member.object
                                                     : expression->data.index_expression.left;
        GrayType *type = inner ? const_walk_expression_type(checker, inner) : NULL;
        /* A destructuring temp is typed as its first slot, but its `.vN`
         * fields are the return values, not memory behind that slot. */
        Symbol *inner_symbol = inner && inner->kind == NODE_LABEL
            ? checker_lookup_symbol(checker, inner->data.label.value) : NULL;
        bool is_tuple_temporary = inner_symbol && inner_symbol->return_count > 0;
        if (!inner || (type && type->kind == TYPE_KIND_POINTER && !is_tuple_temporary)) return false;
        return expression_points_to_const(checker, inner);
    }
    case NODE_POSTFIX_EXPRESSION: {
        /* `pp^` reads the pointer a `^^T` points at, which is a pointer to
         * the const whenever pp is one. */
        if (expression->data.postfix.operator != TOKEN_CARET) return false;
        AstNode *inner = expression->data.postfix.left;
        return is_pointer_to_pointer(const_walk_expression_type(checker, inner)) &&
               expression_points_to_const(checker, inner);
    }
    case NODE_STRUCT_VALUE:
        for (int i = 0; i < expression->data.struct_value.count; i++)
            if (expression_points_to_const(checker, expression->data.struct_value.field_values[i]))
                return true;
        return false;
    case NODE_ARRAY_VALUE:
        for (int i = 0; i < expression->data.array_value.count; i++)
            if (expression_points_to_const(checker, expression->data.array_value.elements[i]))
                return true;
        return false;
    case NODE_MAP_VALUE:
        for (int i = 0; i < expression->data.map_value.count; i++)
            if (expression_points_to_const(checker, expression->data.map_value.values[i]))
                return true;
        return false;
    case NODE_CALL_EXPRESSION: {
        AstNode *field_expression = expression->data.call.function;
        if (field_expression && field_expression->kind == NODE_LABEL && expression->data.call.argument_count == 1) {
            if (strcmp(field_expression->data.label.value, "addr") == 0) {
                AstNode *target = expression->data.call.arguments[0];
                /* A module-level declaration is bound under its module's
                 * spelling, hence checker_lookup_symbol. A pointer root
                 * auto-derefs, so its own constness says nothing about the
                 * pointee. */
                Symbol *symbol = target_root_symbol(checker, target);
                if (symbol && !symbol->is_mutable &&
                    !(symbol->type && symbol->type->kind == TYPE_KIND_POINTER))
                    return true;
                /* The address of a variable that holds a pointer to a const
                 * is a pointer to a pointer at it. */
                if (target->kind == NODE_LABEL && symbol && symbol->is_const_source &&
                    symbol->type && symbol->type->kind == TYPE_KIND_POINTER)
                    return true;
                return place_derefs_const_pointer(checker, target) != NULL;
            }
            if (strcmp(field_expression->data.label.value, "copy") == 0)
                return expression_points_to_const(checker, expression->data.call.arguments[0]);
        }
        FunctionSignature *callee = resolve_call_signature(checker, expression);
        if (!callee) {
            /* A stdlib call (arrays.get_first, maps.get_values, ...), a builtin,
             * or a tagged-enum variant has no FunctionSignature to summarise: assume a
             * pointer-carrying result was read out of its arguments. */
            GrayType *return_type = type_table_get(checker->type_table, expression);
            if (!is_tagged_enum_variant_call(checker, expression) &&
                !(return_type && (return_type->kind == TYPE_KIND_POINTER || return_type->kind == TYPE_KIND_STRUCT ||
                         return_type->kind == TYPE_KIND_ARRAY || return_type->kind == TYPE_KIND_MAP)))
                return false;
            for (int index = 0; index < expression->data.call.argument_count; index++)
                if (expression_points_to_const(checker, expression->data.call.arguments[index]))
                    return true;
            return false;
        }
        ensure_escape_summary(checker, callee);
        if (callee->can_return_const_pointer) return true;
        for (int index = 0; index < expression->data.call.argument_count && index < MAX_TRACKED_PARAMETERS; index++)
            if (((callee->returns_parameter_address >> index) & 1) &&
                expression_points_to_const(checker, expression->data.call.arguments[index]))
                return true;
        return false;
    }
    default:
        return false;
    }
}

/* `dst` now holds a pointer to a const-declared variable, if `value` does. */
static void propagate_const_source(TypeChecker *checker, Symbol *destination_symbol, AstNode *value) {
    if (!destination_symbol || destination_symbol->is_const_source || !destination_symbol->type) return;
    TypeKind kind = destination_symbol->type->kind;
    /* A destructuring temp holds several return values and has no type of
     * its own; the variables bound from it are marked through it. */
    if (kind != TYPE_KIND_POINTER && kind != TYPE_KIND_STRUCT && kind != TYPE_KIND_ARRAY && kind != TYPE_KIND_MAP && kind != TYPE_KIND_ENUM &&
        !(destination_symbol->return_types && destination_symbol->return_count > 0)) return;
    if (expression_points_to_const(checker, value)) destination_symbol->is_const_source = true;
}

/* E3122: report a write to `place` that goes through a pointer to a
 * const-declared variable. */
static bool report_write_through_const_pointer(TypeChecker *checker,
                                               AstNode *report_node, AstNode *place) {
    AstNode *pointer_expression = place_derefs_const_pointer(checker, place);
    if (!pointer_expression) return false;
    if (pointer_expression->kind == NODE_LABEL)
        diagnostic_error_code_formatted(checker->diagnostics, "E3122",
            NODE_FILE(checker, report_node), report_node->token.line, report_node->token.column, 0,
            pointer_expression->data.label.value);
    else
        diagnostic_error_message(checker->diagnostics, "E3122",
            "cannot modify value through a pointer; the pointee is a const-declared variable",
            NODE_FILE(checker, report_node), report_node->token.line, report_node->token.column, 0);
    return true;
}

/* --- pointer_checker_mem_walk: cross-function @mem summary --- */

static void pointer_checker_ensure_mem_summary(TypeChecker *checker, FunctionSignature *function_signature);

/* Which of fs's own parameters `key` is rooted at, by index, and the
 * field-path suffix beyond that parameter (NULL if key IS the bare
 * parameter itself, e.g. key "h.a" against parameter "h" yields suffix
 * ".a"). -1 if key doesn't root at any parameter of fs — a global, an
 * unrelated local, or simply not a match. */
static int pointer_checker_mem_parameter_index_for_key(FunctionSignature *function_signature, const char *arena_key, const char **out_suffix) {
    if (!function_signature->declaration || !arena_key) return -1;
    int parameter_count = function_signature->declaration->data.function_declaration.parameter_count;
    for (int i = 0; i < parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
        const char *parameter_name = function_signature->declaration->data.function_declaration.parameters[i].name;
        if (!parameter_name) continue;
        size_t parameter_name_length = strlen(parameter_name);
        if (strcmp(parameter_name, arena_key) == 0) { *out_suffix = NULL; return i; }
        if (strncmp(arena_key, parameter_name, parameter_name_length) == 0 && arena_key[parameter_name_length] == '.') {
            *out_suffix = arena_key + parameter_name_length;
            return i;
        }
    }
    return -1;
}

/* The path key an arena reference resolves to at a call site, given a
 * callee's arena-carrying parameter and its recorded field suffix (NULL for
 * a bare parameter). `arg` is this call's own argument expression for that
 * parameter — pointer_checker_arena_path_key() resolves it whether it's itself a bare
 * name or already a field chain, so a suffix composes through any depth of
 * forwarding (`cleanup(h)` where cleanup destroys `h.a`, called as
 * `cleanup(outer.h)`, yields "outer.h.a"). */
static const char *pointer_checker_mem_forward_key(TypeChecker *checker, AstNode *argument, const char *suffix) {
    const char *base = pointer_checker_arena_path_key(checker, argument);
    if (!base) return NULL;
    if (!suffix) return base;
    char message[MESSAGE_BUFFER_SIZE];
    snprintf(message, sizeof(message), "%s%s", base, suffix);
    return arena_copy_string(checker->arena, message);
}

/* Scan `fs`'s body for mem.destroy()/mem.reset() calls on one of its own
 * parameters, and for calls to other (already-summarised) functions that
 * destroy/reset one of *their* parameters when the corresponding argument
 * here is one of `fs`'s own parameters — so the effect forwards through a
 * wrapper like `do outer(a Arena) { helper(a) }`. Structural, like
 * escape_walk: looks only at the AST while the summary is being built. */
static void pointer_checker_mem_walk(TypeChecker *checker, FunctionSignature *function_signature, AstNode *node) {
    if (!node || !function_signature->declaration) return;
    switch (node->kind) {
    case NODE_CALL_EXPRESSION: {
        const char *function_name = NULL, *arena = NULL;
        if (pointer_checker_is_mem_call(checker, node, &function_name, &arena) && arena &&
            (strcmp(function_name, "destroy") == 0 || strcmp(function_name, "reset") == 0)) {
            const char *suffix = NULL;
            int i = pointer_checker_mem_parameter_index_for_key(function_signature, arena, &suffix);
            if (i >= 0) {
                if (strcmp(function_name, "destroy") == 0) function_signature->destroys_parameter_arena |= 1ull << i;
                else function_signature->resets_parameter_arena |= 1ull << i;
                if (suffix) function_signature->mem_parameter_field[i] = suffix;
            }
        } else {
            FunctionSignature *callee = resolve_call_signature_in_body(checker,
                function_signature->declaration->data.function_declaration.body, node);
            if (callee && callee != function_signature) {
                pointer_checker_ensure_mem_summary(checker, callee);
                for (int index = 0; index < callee->parameter_count &&
                                index < node->data.call.argument_count && index < MAX_TRACKED_PARAMETERS; index++) {
                    unsigned long long key_effect =
                        (callee->destroys_parameter_arena | callee->resets_parameter_arena) &
                        (1ull << index);
                    if (!key_effect) continue;
                    const char *arena_key = pointer_checker_mem_forward_key(checker,
                        node->data.call.arguments[index], callee->mem_parameter_field[index]);
                    if (!arena_key) continue;
                    const char *suffix = NULL;
                    int i = pointer_checker_mem_parameter_index_for_key(function_signature, arena_key, &suffix);
                    if (i < 0) continue;
                    if (callee->destroys_parameter_arena & (1ull << index))
                        function_signature->destroys_parameter_arena |= 1ull << i;
                    if (callee->resets_parameter_arena & (1ull << index))
                        function_signature->resets_parameter_arena |= 1ull << i;
                    if (suffix) function_signature->mem_parameter_field[i] = suffix;
                }
            } else if (!callee && call_target_is_opaque_function(function_signature, node)) {
                /* An indirect call through a func-typed parameter or an
                 * array/map-held func value: the real callee is unknown, so
                 * conservatively assume any arena handle it receives is
                 * destroyed (#2661, #2692). */
                for (int index = 0; index < node->data.call.argument_count && index < MAX_TRACKED_PARAMETERS; index++) {
                    const char *suffix = NULL;
                    int i = pointer_checker_mem_parameter_index_for_key(function_signature,
                        pointer_checker_arena_path_key(checker, node->data.call.arguments[index]), &suffix);
                    if (i < 0) continue;
                    const char *parameter_type_name = function_signature->declaration->data.function_declaration.parameters[i].type_name;
                    if (!parameter_type_name || !strstr(parameter_type_name, "Arena")) continue;
                    function_signature->destroys_parameter_arena |= 1ull << i;
                    if (suffix) function_signature->mem_parameter_field[i] = suffix;
                }
            }
        }
        for (int i = 0; i < node->data.call.argument_count; i++)
            pointer_checker_mem_walk(checker, function_signature, node->data.call.arguments[i]);
        break;
    }
    case NODE_VARIABLE_DECLARATION:
        pointer_checker_mem_walk(checker, function_signature, node->data.variable_declaration.value);
        break;
    case NODE_ASSIGN_STATEMENT:
        pointer_checker_mem_walk(checker, function_signature, node->data.assign.value);
        break;
    case NODE_BLOCK_STATEMENT:
        for (int i = 0; i < node->data.block.count; i++)
            pointer_checker_mem_walk(checker, function_signature, node->data.block.statements[i]);
        break;
    case NODE_IF_STATEMENT:
        pointer_checker_mem_walk(checker, function_signature, node->data.if_statement.consequence);
        pointer_checker_mem_walk(checker, function_signature, node->data.if_statement.alternative);
        break;
    case NODE_WHEN_STATEMENT:
        for (int i = 0; i < node->data.when_statement.case_count; i++)
            pointer_checker_mem_walk(checker, function_signature, node->data.when_statement.cases[i].body);
        pointer_checker_mem_walk(checker, function_signature, node->data.when_statement.default_body);
        break;
    case NODE_FOR_STATEMENT:      pointer_checker_mem_walk(checker, function_signature, node->data.for_statement.body); break;
    case NODE_FOR_EACH_STATEMENT: pointer_checker_mem_walk(checker, function_signature, node->data.for_each.body); break;
    case NODE_WHILE_STATEMENT:    pointer_checker_mem_walk(checker, function_signature, node->data.while_statement.body); break;
    case NODE_LOOP_STATEMENT:     pointer_checker_mem_walk(checker, function_signature, node->data.loop_statement.body); break;
    case NODE_EXPRESSION_STATEMENT:     pointer_checker_mem_walk(checker, function_signature, node->data.expression_statement.expression); break;
    case NODE_ENSURE_STATEMENT:   pointer_checker_mem_walk(checker, function_signature, node->data.ensure_statement.expression); break;
    case NODE_RETURN_STATEMENT:
        for (int i = 0; i < node->data.return_statement.count; i++)
            pointer_checker_mem_walk(checker, function_signature, node->data.return_statement.values[i]);
        break;
    default:
        break;
    }
}

/* bitmask: bit i set if return-value expression `node` yields a @mem pointer
 * allocated from the arena named by `fs`'s parameter i — mem.alloc(a, x) /
 * mem.init(a, T) directly, through a local variable declared from one, or
 * forwarded through another summarised call's own returns_parameter_mem_allocation.
 * Mirrors return_expression_parameter_bits' shape, for arena allocation instead of
 * pointer escape. */
/* Fills *out_direct (bit i: node itself is a @mem pointer allocated from
 * parameter i's arena) and *out_field (bit i: node is an aggregate — a
 * struct/array/map literal, or a call forwarding one — with such a pointer
 * buried inside it) for a return-value expression. A bit is set in at most
 * one of the two; mirrors the mem_arena / field_mem_arena split
 * pointer_checker_bind_mem_pointer() records on a Symbol, but for a FunctionSignature's summary of
 * its own return value instead. */
static void pointer_checker_return_expression_mem_bits(TypeChecker *checker, FunctionSignature *function_signature, AstNode *node,
                                    unsigned long long *out_direct,
                                    unsigned long long *out_field) {
    if (!node || !function_signature->declaration) return;
    if (node->kind == NODE_LABEL) {
        AstNode *initializer = local_initializer(function_signature->declaration->data.function_declaration.body,
                                          node->data.label.value);
        if (initializer && initializer != node)
            pointer_checker_return_expression_mem_bits(checker, function_signature, initializer, out_direct, out_field);
        return;
    }
    int parameter_count = function_signature->declaration->data.function_declaration.parameter_count;
    switch (node->kind) {
    case NODE_STRUCT_VALUE:
        for (int i = 0; i < node->data.struct_value.count; i++) {
            unsigned long long direct_bits = 0, field_bits = 0;
            pointer_checker_return_expression_mem_bits(checker, function_signature,
                node->data.struct_value.field_values[i], &direct_bits, &field_bits);
            *out_field |= direct_bits | field_bits;
        }
        return;
    case NODE_ARRAY_VALUE:
        for (int i = 0; i < node->data.array_value.count; i++) {
            unsigned long long direct_bits = 0, field_bits = 0;
            pointer_checker_return_expression_mem_bits(checker, function_signature,
                node->data.array_value.elements[i], &direct_bits, &field_bits);
            *out_field |= direct_bits | field_bits;
        }
        return;
    case NODE_MAP_VALUE:
        for (int i = 0; i < node->data.map_value.count; i++) {
            unsigned long long direct_bits = 0, field_bits = 0;
            pointer_checker_return_expression_mem_bits(checker, function_signature, node->data.map_value.values[i], &direct_bits, &field_bits);
            *out_field |= direct_bits | field_bits;
        }
        return;
    default:
        break;
    }
    if (node->kind != NODE_CALL_EXPRESSION) return;
    if (is_tagged_enum_variant_call(checker, node)) {
        /* Enum.Variant(args): same treatment as a struct/array/map literal
         * above — see pointer_checker_mem_pointer_in_expression's identical case. */
        for (int i = 0; i < node->data.call.argument_count; i++) {
            unsigned long long direct_bits = 0, field_bits = 0;
            pointer_checker_return_expression_mem_bits(checker, function_signature, node->data.call.arguments[i], &direct_bits, &field_bits);
            *out_field |= direct_bits | field_bits;
        }
        return;
    }
    const char *function_name = NULL, *arena = NULL;
    if (pointer_checker_is_mem_call(checker, node, &function_name, &arena) && arena &&
        (strcmp(function_name, "init") == 0 || strcmp(function_name, "alloc") == 0)) {
        for (int i = 0; i < parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
            const char *parameter_name = function_signature->declaration->data.function_declaration.parameters[i].name;
            if (parameter_name && strcmp(parameter_name, arena) == 0) *out_direct |= 1ull << i;
        }
        return;
    }
    FunctionSignature *callee = resolve_call_signature_in_body(checker, function_signature->declaration->data.function_declaration.body, node);
    if (!callee || callee == function_signature) return;
    pointer_checker_ensure_mem_summary(checker, callee);
    for (int index = 0; index < callee->parameter_count &&
                    index < node->data.call.argument_count && index < MAX_TRACKED_PARAMETERS; index++) {
        unsigned long long callee_bit = 1ull << index;
        if (!((callee->returns_parameter_mem_allocation | callee->returns_parameter_mem_allocation_field) &
              callee_bit))
            continue;
        AstNode *argument = node->data.call.arguments[index];
        if (argument->kind != NODE_LABEL) continue;
        bool via_field = (callee->returns_parameter_mem_allocation_field & callee_bit) != 0;
        for (int i = 0; i < parameter_count && i < MAX_TRACKED_PARAMETERS; i++) {
            const char *parameter_name = function_signature->declaration->data.function_declaration.parameters[i].name;
            if (!parameter_name || strcmp(parameter_name, argument->data.label.value) != 0) continue;
            if (via_field) *out_field |= 1ull << i;
            else *out_direct |= 1ull << i;
        }
    }
}

/* OR together pointer_checker_return_expression_mem_bits() over every `return` reachable in a
 * statement subtree. Mirrors return_statement_parameter_bits. */
static void pointer_checker_return_statement_mem_bits(TypeChecker *checker, FunctionSignature *function_signature, AstNode *node,
                                    unsigned long long *out_direct,
                                    unsigned long long *out_field) {
    if (!node) return;
    switch (node->kind) {
    case NODE_RETURN_STATEMENT:
        for (int i = 0; i < node->data.return_statement.count; i++)
            pointer_checker_return_expression_mem_bits(checker, function_signature, node->data.return_statement.values[i],
                                    out_direct, out_field);
        break;
    case NODE_BLOCK_STATEMENT:
        for (int i = 0; i < node->data.block.count; i++)
            pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.block.statements[i],
                                    out_direct, out_field);
        break;
    case NODE_IF_STATEMENT:
        pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.if_statement.consequence, out_direct, out_field);
        pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.if_statement.alternative, out_direct, out_field);
        break;
    case NODE_WHEN_STATEMENT:
        for (int i = 0; i < node->data.when_statement.case_count; i++)
            pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.when_statement.cases[i].body,
                                    out_direct, out_field);
        pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.when_statement.default_body, out_direct, out_field);
        break;
    case NODE_FOR_STATEMENT:
        pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.for_statement.body, out_direct, out_field);
        break;
    case NODE_FOR_EACH_STATEMENT:
        pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.for_each.body, out_direct, out_field);
        break;
    case NODE_WHILE_STATEMENT:
        pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.while_statement.body, out_direct, out_field);
        break;
    case NODE_LOOP_STATEMENT:
        pointer_checker_return_statement_mem_bits(checker, function_signature, node->data.loop_statement.body, out_direct, out_field);
        break;
    default:
        break;
    }
}

/* Lazily compute and memoise `fs`'s cross-function @mem summary. Mirrors
 * ensure_escape_summary: a function caught mid-computation (recursion) is
 * left with whatever partial summary it has — conservative, never a false
 * negative turned into a crash, just a possibly-missed forwarding case. */
static void pointer_checker_ensure_mem_summary(TypeChecker *checker, FunctionSignature *function_signature) {
    if (!function_signature || function_signature->mem_state != 0) return;
    function_signature->mem_state = 1;
    function_signature->destroys_parameter_arena = 0;
    function_signature->resets_parameter_arena = 0;
    memset(function_signature->mem_parameter_field, 0, sizeof function_signature->mem_parameter_field);
    function_signature->returns_parameter_mem_allocation = 0;
    function_signature->returns_parameter_mem_allocation_field = 0;
    AstNode *body = (function_signature->declaration && function_signature->declaration->kind == NODE_FUNCTION_DECLARATION)
                    ? function_signature->declaration->data.function_declaration.body : NULL;
    if (body && function_signature->declaration->data.function_declaration.parameter_count <= 64) {
        bool saved = checker->is_pointer_checker_in_mem_summary;
        checker->is_pointer_checker_in_mem_summary = true;
        pointer_checker_mem_walk(checker, function_signature, body);
        pointer_checker_return_statement_mem_bits(checker, function_signature, body,
            &function_signature->returns_parameter_mem_allocation, &function_signature->returns_parameter_mem_allocation_field);
        checker->is_pointer_checker_in_mem_summary = saved;
    }
    function_signature->mem_state = 2;
}

static int call_result_origin(TypeChecker *checker, AstNode *call,
                              const char **out_name) {
    FunctionSignature *function_signature = resolve_call_signature(checker, call);
    if (!function_signature) return 0;
    unsigned long long bits = returns_parameter_address_of(checker, function_signature);
    if (!bits) return 0;
    int best = 0;
    const char *best_name = NULL;
    for (int i = 0; i < function_signature->parameter_count &&
                    i < call->data.call.argument_count && i < MAX_TRACKED_PARAMETERS; i++) {
        if (!(bits & (1ull << i))) continue;
        const char *name = NULL;
        int origin_depth = pointer_origin_of(checker, call->data.call.arguments[i], &name);
        if (origin_depth > best) { best = origin_depth; best_name = name; }
    }
    if (best) *out_name = best_name;
    return best;
}

static int container_literal_origin(TypeChecker *checker, AstNode *node,
                                    const char **out_name);

/* Deepest lifetime origin an expression carries: a tracked pointer (the
 * direct addr()/raw() form, one laundered through a variable, or one read
 * back out of a container) combined with an address buried inside a
 * struct / array / map literal. */
static int expression_origin(TypeChecker *checker, AstNode *value,
                             const char **out_name) {
    const char *direct_name = NULL, *literal_name = NULL;
    int direct_depth = pointer_origin_of(checker, value, &direct_name);
    int literal_depth = container_literal_origin(checker, value, &literal_name);
    if (literal_depth > direct_depth) { *out_name = literal_name; return literal_depth; }
    if (direct_depth) { *out_name = direct_name; return direct_depth; }
    return 0;
}

/* Deepest origin among a call's own arguments — see the forward declaration
 * near call_result_origin for when this applies. Gated on the call's own
 * result type being able to structurally carry a pointer (a pointer, or a
 * struct/array/map that might hold one buried inside): arrays.get_first(arr)
 * needs this (returns ^T, forwarded from arr), arrays.contains(arr, x) does
 * not (returns bool — no argument's address could possibly be smuggled out
 * through it, whatever arr holds). Without the gate, any stdlib call taking
 * an address-carrying argument would be flagged regardless of what it
 * actually returns. */
static int stdlib_call_argument_origin(TypeChecker *checker, AstNode *call,
                                  const char **out_name) {
    GrayType *return_type = resolve_expression(checker, call);
    if (!return_type || !(return_type->kind == TYPE_KIND_POINTER || return_type->kind == TYPE_KIND_STRUCT ||
                 return_type->kind == TYPE_KIND_ARRAY || return_type->kind == TYPE_KIND_MAP))
        return 0;
    int best = 0;
    const char *best_name = NULL;
    for (int i = 0; i < call->data.call.argument_count; i++) {
        const char *name = NULL;
        int origin_depth = expression_origin(checker, call->data.call.arguments[i], &name);
        if (origin_depth > best) { best = origin_depth; best_name = name; }
    }
    if (best) *out_name = best_name;
    return best;
}

/* Deepest pointer-origin buried in a struct / array / map literal, or 0.
 * A container built with `Field{p: addr(local)}`, `{addr(local)}`, or
 * `{"k": addr(local)}` carries the pointee's lifetime even though the
 * address sits inside an element. Recurses through nested literals. */
static int container_literal_origin(TypeChecker *checker, AstNode *node,
                                    const char **out_name) {
    if (!node) return 0;
    int best = 0;
    const char *best_name = NULL;
    switch (node->kind) {
    case NODE_STRUCT_VALUE:
        for (int i = 0; i < node->data.struct_value.count; i++) {
            const char *name = NULL;
            int origin_depth = expression_origin(checker,
                        node->data.struct_value.field_values[i], &name);
            if (origin_depth > best) { best = origin_depth; best_name = name; }
        }
        break;
    case NODE_ARRAY_VALUE:
        for (int i = 0; i < node->data.array_value.count; i++) {
            const char *name = NULL;
            int origin_depth = expression_origin(checker,
                        node->data.array_value.elements[i], &name);
            if (origin_depth > best) { best = origin_depth; best_name = name; }
        }
        break;
    case NODE_MAP_VALUE:
        for (int i = 0; i < node->data.map_value.count; i++) {
            const char *name = NULL;
            int origin_depth = expression_origin(checker, node->data.map_value.values[i], &name);
            if (origin_depth > best) { best = origin_depth; best_name = name; }
            name = NULL;
            origin_depth = expression_origin(checker, node->data.map_value.keys[i], &name);
            if (origin_depth > best) { best = origin_depth; best_name = name; }
        }
        break;
    case NODE_CALL_EXPRESSION:
        if (is_tagged_enum_variant_call(checker, node)) {
            /* Enum.Variant(args) / .Variant(args): the payload is a value
             * carrier exactly like a struct/array/map literal, but resolves
             * to no FunctionSignature so it needs its own recognizer rather than
             * falling into a normal call's lookup — the enum's own type is
             * TYPE_KIND_ENUM, which the general stdlib_call_argument_origin fallback
             * below does not treat as capable of carrying a pointer. */
            for (int i = 0; i < node->data.call.argument_count; i++) {
                const char *name = NULL;
                int origin_depth = expression_origin(checker, node->data.call.arguments[i], &name);
                if (origin_depth > best) { best = origin_depth; best_name = name; }
            }
        } else {
            /* An ordinary call whose result may carry one of its own
             * arguments' address. A resolved user function keeps its own
             * precise, computed returns_parameter_address summary (call_result_
             * origin — pointer_origin_of already returns the same thing for
             * a bare `p = f(...)`). Anything without a FunctionSignature — a stdlib
             * module call (arrays.get_first, maps.get_values, ...) or a
             * builtin (copy()) — falls back to the conservative
             * arguments-based guess instead, since none of those get an
             * escape summary to consult. Recorded here too so a multi-return
             * temp's per-slot reads see it: `p, n = f(...)` desugars to
             * `_tmp = f(...); p = _tmp.v0; n = _tmp.v1`, and the second
             * statement's value is a NODE_MEMBER_EXPRESSION whose origin lookup
             * (pointer_origin_of's NODE_MEMBER_EXPRESSION case) consults field_
             * origin_depth — this function's result — not origin_depth,
             * which only the first statement's plain call expression sets. */
            best = call_result_origin(checker, node, &best_name);
            if (!best && !resolve_call_signature(checker, node))
                best = stdlib_call_argument_origin(checker, node, &best_name);
        }
        break;
    default:
        return 0;
    }
    if (best) *out_name = best_name;
    return best;
}

/* The name the programmer wrote, never the module-prefixed internal one.
 * FunctionSignature.name is the flattened lookup key (e.g. "mod_size" for `size`
 * imported from module `mod`); the user-facing name lives on the decl.
 * Diagnostics and namespace-collision checks must use this, not .name.
 *
 * The declaration node's own .name is the name as written — merging an
 * import no longer rewrites it, so original_name stays NULL and is only a
 * fallback for whatever still sets it. Reading .name is what keeps a
 * mangled key out of user-facing text. */
static const char *function_display_name(const FunctionSignature *function_signature) {
    if (function_signature && function_signature->declaration && function_signature->declaration->kind == NODE_FUNCTION_DECLARATION) {
        return FUNCTION_DISPLAY_NAME(function_signature->declaration);
    }
    return function_signature ? function_signature->name : "";
}

/* E3163 ("a helper's summary escapes one of its own parameters" — into a
 * global, another parameter's reachable storage, or a container sink) plus
 * the @mem arena-lifecycle propagation, for a call to `csig` against `node`'s
 * current arguments. `reported_arg` is the bitmask of argument positions an
 * earlier direct addr()/raw()-alongside-outer-arg heuristic already reported,
 * so this does not double-report them.
 *
 * A shared function rather than inline in resolve_call_expression because instance
 * dispatch (s.stash(addr(y))) needs it run a second time, later: at the point
 * resolve_call_expression's own copy of this check runs, resolve_call_signature() cannot
 * find a FunctionSignature for the call — the callee is still spelled with the instance
 * as the member-expr's object, not the struct's type name, and self has not
 * yet been prepended into args[0]. That rewrite (retarget_member_object() +
 * the self-arg splice) happens later in the same function, inside
 * resolve_struct_or_module_call(). Without a second call from there, every
 * escape/@mem check silently no-ops for instance-dispatch struct functions —
 * the language's most common calling convention for the struct-function
 * feature. (Static dispatch, Struct.func(self: s, ...), needs no second call:
 * the object already names the struct and self is already an explicit
 * argument, so the first, early check already sees the right shape.) */
static void apply_call_parameter_escape_and_mem_effects(TypeChecker *checker,
    AstNode *node, FunctionSignature *callee_signature, unsigned long long reported_argument_bits) {
    if (!callee_signature) return;
    int argument_count = node->data.call.argument_count;
    ensure_escape_summary(checker, callee_signature);
    for (int argument_index = 0; argument_index < argument_count && argument_index < callee_signature->parameter_count && argument_index < MAX_TRACKED_PARAMETERS; argument_index++) {
        signed char parameter_escape = callee_signature->parameter_escape_into[argument_index];
        if (parameter_escape == PARAMETER_ESCAPE_NONE) continue;
        if ((reported_argument_bits >> argument_index) & 1) continue;
        AstNode *argument = node->data.call.arguments[argument_index];
        const char *original_name = NULL;
        int origin_depth = expression_origin(checker, argument, &original_name);
        if (origin_depth <= 0) {
            /* Not a stack pointer, but maybe a @mem arena pointer laundered
             * into caller-visible storage by this helper — same E3169 as a
             * direct `g = p` when this function later tears the arena down. */
            pointer_checker_check_mem_escape(checker, argument, argument);
            continue;
        }
        int sink_depth;
        const char *sink_name;
        const char *via_global_name = NULL;
        if (parameter_escape == PARAMETER_ESCAPE_GLOBAL && callee_signature->parameter_escape_via_function[argument_index] >= 0) {
            /* The escape is only a forward into an indirect call through one
             * of callee_signature's func-typed parameters. When this call supplies a known
             * function for it, that function's own summary decides. */
            int function_parameter_index = callee_signature->parameter_escape_via_function[argument_index];
            int position = callee_signature->parameter_escape_via_position[argument_index];
            const char *target = function_parameter_index < argument_count
                ? function_reference_target_name(node->data.call.arguments[function_parameter_index]) : NULL;
            FunctionSignature *callback_signature = target ? find_function(checker, target) : NULL;
            if (callback_signature && position < callback_signature->parameter_count && position < MAX_TRACKED_PARAMETERS) {
                ensure_escape_summary(checker, callback_signature);
                if (callback_signature->parameter_escape_into[position] == PARAMETER_ESCAPE_NONE) continue;
                via_global_name = callback_signature->parameter_escape_global_name[position];
            }
        }
        if (parameter_escape == PARAMETER_ESCAPE_GLOBAL) {
            /* A global outlives the program, so only an origin genuinely
             * local to *this* function escapes it — a module-level source
             * (addr of another global) is program-lifetime and fine. */
            sink_depth = checker->current_function_scope_depth > 0
                ? checker->current_function_scope_depth - 1 : 0;
            /* The specific global is only known when the escape was traced
             * through a direct callee (parameter_escape_global_name[a] set at
             * the point the escape was recorded). An opaque call target
             * (record_parameter_escape(..., PARAMETER_ESCAPE_GLOBAL, NULL)) means
             * some global is reached but which one is unknowable — falling
             * back to original_name (the origin/pointee name) here would print the
             * same name in both message slots. */
            sink_name = via_global_name ? via_global_name
                : (argument_index < MAX_TRACKED_PARAMETERS && callee_signature->parameter_escape_global_name[argument_index])
                ? callee_signature->parameter_escape_global_name[argument_index] : "a global";
        } else {
            const char *destination_root = (parameter_escape < argument_count)
                ? assignment_target_root_name(node->data.call.arguments[parameter_escape])
                : NULL;
            sink_depth = destination_root
                ? symbol_scope_depth(checker->current_scope, destination_root) : 0;
            sink_name = destination_root ? destination_root : original_name;
        }
        if (origin_depth > sink_depth)
            diagnostic_error_code_formatted(checker->diagnostics, "E3163",
                NODE_FILE(checker, argument), argument->token.line,
                argument->token.column, 0, sink_name, original_name);
    }
    /* Pointer checker: a call to a helper that destroys/resets one of its own
     * @mem arena parameters — the parameter itself, or a field of it
     * (callee_signature->mem_parameter_field) — applies that same effect to the caller's
     * arena state here, at the call site — closing the "across a function
     * call" gap in E3164/E3165/E3166. Only an argument pointer_checker_arena_path_key()
     * can name (a bare variable, or a field-access chain) is traced;
     * anything else is left alone. */
    pointer_checker_ensure_mem_summary(checker, callee_signature);
    unsigned long long mem_effect =
        callee_signature->destroys_parameter_arena | callee_signature->resets_parameter_arena;
    for (int argument_index = 0; argument_index < argument_count && argument_index < callee_signature->parameter_count && argument_index < MAX_TRACKED_PARAMETERS && mem_effect; argument_index++) {
        if (!(mem_effect & (1ull << argument_index))) continue;
        const char *arena_key = pointer_checker_mem_forward_key(checker, node->data.call.arguments[argument_index],
                                             callee_signature->mem_parameter_field[argument_index]);
        if (!arena_key) continue;
        bool destroys = (callee_signature->destroys_parameter_arena & (1ull << argument_index)) != 0;
        pointer_checker_apply_arena_lifecycle(checker, arena_key, destroys,
                                 node, function_display_name(callee_signature));
    }
}

/* E3154, forwarded through a pointer-parameter function boundary (#2732): the
 * direct check at an extern.func() call site only sees a stack address
 * written out inline (or laundered through a local) in the *same* function
 * as the call. A helper that takes a `^T` parameter and passes it straight
 * into its own extern. call defeats that check entirely — the parameter is
 * just an opaque value from the callee's point of view, with no origin to
 * trace. `csig`'s passes_parameter_to_extern summary (computed structurally by
 * escape_walk, the same pass that computes returns_parameter_address) names which
 * of its parameters reach extern. that way; this applies it at the call
 * site, exactly like a direct extern.func(addr(local)) would be. */
static void apply_call_parameter_extern_effects(TypeChecker *checker,
    AstNode *node, FunctionSignature *callee_signature) {
    if (!callee_signature || checker->current_function_scope_depth <= 0) return;
    ensure_escape_summary(checker, callee_signature);
    if (!callee_signature->passes_parameter_to_extern) return;
    int argument_count = node->data.call.argument_count;
    for (int argument_index = 0; argument_index < argument_count && argument_index < callee_signature->parameter_count && argument_index < MAX_TRACKED_PARAMETERS; argument_index++) {
        if (!((callee_signature->passes_parameter_to_extern >> argument_index) & 1)) continue;
        AstNode *argument = node->data.call.arguments[argument_index];
        const char *root = NULL;
        int origin_depth = expression_origin(checker, argument, &root);
        if (origin_depth > 0 && origin_depth >= checker->current_function_scope_depth && root) {
            diagnostic_error_code_formatted(checker->diagnostics, "E3154",
                NODE_FILE(checker, argument), argument->token.line, argument->token.column, 0,
                root);
        }
    }
}

/* E3122, forwarded through a pointer-parameter function boundary: writing
 * through a pointer to a const-declared variable is caught where the write
 * is spelled (`p^ = v`), but a helper that takes a `^T` parameter and writes
 * through it never sees the const — the pointer is just an opaque parameter.
 * `csig`'s writes_through_parameter summary names which parameters it writes
 * through; this refuses a pointer to a constant for any of them. */
static void apply_call_parameter_write_effects(TypeChecker *checker,
    AstNode *node, FunctionSignature *callee_signature) {
    if (!callee_signature || !callee_signature->declaration || callee_signature->declaration->kind != NODE_FUNCTION_DECLARATION) return;
    ensure_escape_summary(checker, callee_signature);
    if (!callee_signature->writes_through_parameter) return;
    int argument_count = node->data.call.argument_count;
    for (int argument_index = 0; argument_index < argument_count && argument_index < callee_signature->parameter_count && argument_index < MAX_TRACKED_PARAMETERS; argument_index++) {
        if (!((callee_signature->writes_through_parameter >> argument_index) & 1)) continue;
        AstNode *argument = node->data.call.arguments[argument_index];
        if (is_pointer_to_pointer(const_walk_expression_type(checker, argument))) continue;
        if (!expression_points_to_const(checker, argument)) continue;
        char *message = typechecker_format(checker,
            "cannot pass a pointer to a const-declared variable to parameter '%s' of '%s'; the function modifies the value through it",
            callee_signature->declaration->data.function_declaration.parameters[argument_index].name,
            FUNCTION_DISPLAY_NAME(callee_signature->declaration));
        typechecker_error_at(checker, "E3122", argument, message);
    }
}

/* --- #deprecated warning helpers ---
 * Fire W3007 at every genuine reference site (not internal lookup/diagnostic
 * helper calls). Each caller is responsible for only calling these from a
 * spot that represents a real user reference — see call sites. */

static void warn_deprecated(TypeChecker *checker, AstNode *node, const char *kind,
    const char *display_name, const char *message) {
    char *warning_message = message
        ? typechecker_format(checker, "%s '%s' is deprecated: %s", kind, display_name, message)
        : typechecker_format(checker, "%s '%s' is deprecated", kind, display_name);
    diagnostic_warning_message(checker->diagnostics, "W3007", warning_message,
        NODE_FILE(checker, node), node->token.line, node->token.column, 0);
}

/* Exempt a deprecated function's own recursive calls to itself (pointer
 * identity on FunctionSignature.decl, not name — struct functions are registered
 * under a prefixed lookup key that never matches the plain AST name). */
static void warn_if_function_deprecated(TypeChecker *checker, AstNode *node, FunctionSignature *signature) {
    if (!signature || !signature->is_deprecated) return;
    if (checker->current_function_declaration && signature->declaration == checker->current_function_declaration) return;
    /* function_display_name() only strips module-import prefixes via
     * original_name; struct-scoped functions are registered under a
     * "StructName_func" key with no original_name set, so it would
     * leak the prefixed key. FUNCTION_DISPLAY_NAME reads the AST node's
     * own (never-prefixed) .name field instead. */
    const char *display = signature->declaration ? FUNCTION_DISPLAY_NAME(signature->declaration) : function_display_name(signature);
    warn_deprecated(checker, node, "function", display, signature->deprecated_message);
}

/* E5047: a #test function is an entry point for `gray test`; a normal build
 * strips it, so any call or reference from other code would dangle. Called
 * from every path that resolves a bare/qualified function to a FunctionSignature. */
static void reject_test_function_reference(TypeChecker *checker, AstNode *node, FunctionSignature *signature) {
    if (!signature || !signature->declaration || signature->declaration->kind != NODE_FUNCTION_DECLARATION) return;
    if (!signature->declaration->data.function_declaration.is_test) return;
    diagnostic_error_code_formatted(checker->diagnostics, "E5047",
        NODE_FILE(checker, node), node->token.line, node->token.column, 0,
        function_display_name(signature));
}

/* Exempt references to a deprecated struct's own type from within its own
 * struct-functions (same mechanism as the existing private-field-access
 * check: checker->current_struct_name, set/restored around struct-function
 * body typechecking). Does NOT cascade to that struct's struct-function
 * calls — those are independent and only warn if separately deprecated. */
static void warn_if_struct_deprecated(TypeChecker *checker, AstNode *node, StructInfo *struct_info) {
    if (!struct_info || !struct_info->is_deprecated) return;
    if (checker->current_struct_name && strcmp(checker->current_struct_name, struct_info->struct_name) == 0) return;
    warn_deprecated(checker, node, "struct", struct_info->display_name, struct_info->deprecated_message);
}

/* Enums have no executable body that could reference themselves, so no
 * self-reference exemption is needed here. */
static void warn_if_enum_deprecated(TypeChecker *checker, AstNode *node, int enum_index) {
    if (enum_index < 0 || !checker->is_enum_deprecated[enum_index]) return;
    warn_deprecated(checker, node, "enum", checker->enum_display_names[enum_index],
        checker->enum_deprecated_messages[enum_index]);
}

/* Check a declared type-name string (var-decl / param / return / field
 * annotation) against the struct and enum registries and warn if it
 * names a deprecated one. Bare names only — [Old]/^Old wrappers are not
 * unwrapped, matching the scope of this pass.
 *
 * self_struct_name: pass the enclosing struct's own name when checking a
 * struct-scoped function's param/return types, so a deprecated struct's
 * own `self StructName` parameter is exempt the same way its body is
 * (checker->current_struct_name isn't set yet at signature-registration
 * time, so warn_if_struct_deprecated's own self-check can't catch this —
 * it only guards references from inside an already-typechecked body). */
static void warn_if_type_name_deprecated(TypeChecker *checker, AstNode *node, const char *type_name,
    const char *self_struct_name) {
    if (!type_name) return;
    if (self_struct_name && strcmp(type_name, self_struct_name) == 0) return;
    StructInfo *struct_info = find_struct(checker, type_name);
    if (struct_info) {
        warn_if_struct_deprecated(checker, node, struct_info);
        return;
    }
    int enum_index = find_enum_index(checker, type_name);
    if (enum_index >= 0) warn_if_enum_deprecated(checker, node, enum_index);
}

/* --- Stdlib argument kind validation --- */

typedef enum {
    /* EXPECTED_ARGUMENT_I64 is an i64 parameter, EXPECTED_ARGUMENT_U64 a u64 one, EXPECTED_ARGUMENT_F64 an f64 one;
     * an argument is checked as that type. EXPECTED_ARGUMENT_NUMBER takes any number. */
    EXPECTED_ARGUMENT_STRING, EXPECTED_ARGUMENT_I64, EXPECTED_ARGUMENT_U64, EXPECTED_ARGUMENT_F64, EXPECTED_ARGUMENT_BOOL, EXPECTED_ARGUMENT_ARRAY, EXPECTED_ARGUMENT_MAP, EXPECTED_ARGUMENT_ANY, EXPECTED_ARGUMENT_NUMBER, EXPECTED_ARGUMENT_CHAR, EXPECTED_ARGUMENT_CHANNEL,
    EXPECTED_ARGUMENT_BUILDER, EXPECTED_ARGUMENT_UUID, EXPECTED_ARGUMENT_U8_ARRAY, EXPECTED_ARGUMENT_I64_POINTER,
    /* A value stored into or compared with the array in argument 0: checked
     * as that array's element type. */
    EXPECTED_ARGUMENT_ELEMENT_OF_FIRST,
    /* A second array of argument 0's type. */
    EXPECTED_ARGUMENT_SAME_AS_FIRST,
    /* One of the numbers math.min/max/clamp combine: every such argument is
     * checked as their common type (as a binary operator would type them). */
    EXPECTED_ARGUMENT_COMMON_NUMBER,
    /* A type name, not a value. Declaring the position here is what keeps
     * it out of value resolution — see argument_is_type_position(). */
    EXPECTED_ARGUMENT_TYPE
} ExpectedArgumentKind;

static bool argument_kind_matches(ExpectedArgumentKind expected, GrayType *actual) {
    if (!actual || actual->kind == TYPE_KIND_UNKNOWN) return true; /* can't validate */
    switch (expected) {
    case EXPECTED_ARGUMENT_STRING: return actual->kind == TYPE_KIND_STRING;
    case EXPECTED_ARGUMENT_I64:
    case EXPECTED_ARGUMENT_U64:    return actual->kind == TYPE_KIND_SIGNED_INTEGER || actual->kind == TYPE_KIND_UNSIGNED_INTEGER;
    case EXPECTED_ARGUMENT_F64:  return actual->kind == TYPE_KIND_FLOATING_POINT;
    case EXPECTED_ARGUMENT_BOOL:   return actual->kind == TYPE_KIND_BOOL;
    case EXPECTED_ARGUMENT_ARRAY:  return actual->kind == TYPE_KIND_ARRAY;
    case EXPECTED_ARGUMENT_MAP:    return actual->kind == TYPE_KIND_MAP;
    case EXPECTED_ARGUMENT_ANY:    return true;
    case EXPECTED_ARGUMENT_NUMBER: return actual->kind == TYPE_KIND_SIGNED_INTEGER || actual->kind == TYPE_KIND_UNSIGNED_INTEGER ||
                            actual->kind == TYPE_KIND_FLOATING_POINT;
    case EXPECTED_ARGUMENT_CHAR:   return actual->kind == TYPE_KIND_CHAR;
    case EXPECTED_ARGUMENT_CHANNEL: return actual->kind == TYPE_KIND_STRUCT &&
                             actual->name && strcmp(actual->name, "Channel") == 0;
    case EXPECTED_ARGUMENT_BUILDER: return actual->kind == TYPE_KIND_STRUCT &&
                             actual->name && strcmp(actual->name, "Builder") == 0;
    case EXPECTED_ARGUMENT_UUID:    return actual->kind == TYPE_KIND_STRUCT &&
                             actual->name && strcmp(actual->name, "UUID") == 0;
    case EXPECTED_ARGUMENT_U8_ARRAY: return actual->kind == TYPE_KIND_ARRAY && actual->element_type &&
                             strcmp(actual->element_type, "u8") == 0;
    /* The atomic operations read and write exactly 8 bytes as an int64. */
    case EXPECTED_ARGUMENT_I64_POINTER: return actual->kind == TYPE_KIND_POINTER && actual->element_type &&
                             strcmp(actual->element_type, "i64") == 0;
    /* Validated by name, never by resolved type — the argument is a type
     * name and is never resolved as a value. */
    case EXPECTED_ARGUMENT_TYPE:   return true;
    /* Checked against the type derived from the other arguments. */
    case EXPECTED_ARGUMENT_ELEMENT_OF_FIRST:
    case EXPECTED_ARGUMENT_SAME_AS_FIRST: return true;
    case EXPECTED_ARGUMENT_COMMON_NUMBER: return actual->kind == TYPE_KIND_SIGNED_INTEGER || actual->kind == TYPE_KIND_UNSIGNED_INTEGER ||
                                   actual->kind == TYPE_KIND_FLOATING_POINT;
    }
    return true;
}

static const char *expected_kind_name(ExpectedArgumentKind kind) {
    switch (kind) {
    case EXPECTED_ARGUMENT_STRING: return "string";
    case EXPECTED_ARGUMENT_I64:    return "integer";
    case EXPECTED_ARGUMENT_U64:    return "u64";
    case EXPECTED_ARGUMENT_F64:  return "f64";
    case EXPECTED_ARGUMENT_BOOL:   return "bool";
    case EXPECTED_ARGUMENT_ARRAY:  return "array";
    case EXPECTED_ARGUMENT_MAP:    return "map";
    case EXPECTED_ARGUMENT_ANY:    return "any";
    case EXPECTED_ARGUMENT_NUMBER: return "number";
    case EXPECTED_ARGUMENT_CHAR:   return "char";
    case EXPECTED_ARGUMENT_CHANNEL: return "Channel";
    case EXPECTED_ARGUMENT_BUILDER: return "Builder";
    case EXPECTED_ARGUMENT_UUID:    return "UUID";
    case EXPECTED_ARGUMENT_U8_ARRAY: return "[u8]";
    case EXPECTED_ARGUMENT_I64_POINTER: return "^i64";
    case EXPECTED_ARGUMENT_TYPE:   return "a type name";
    case EXPECTED_ARGUMENT_ELEMENT_OF_FIRST: return "an element of the array";
    case EXPECTED_ARGUMENT_SAME_AS_FIRST: return "an array of the same type";
    case EXPECTED_ARGUMENT_COMMON_NUMBER: return "number";
    }
    return "unknown";
}

/* --- Unified stdlib function metadata registry ---
 * Single table that consolidates fallibility, arg count range, and
 * per-argument type expectations for every stdlib function. */

typedef enum {
    FALLIBLE_TYPE_NONE = -1,
    FALLIBLE_TYPE_BOOL, FALLIBLE_TYPE_I64, FALLIBLE_TYPE_U64, FALLIBLE_TYPE_F64, FALLIBLE_TYPE_STRING,
    FALLIBLE_TYPE_ARRAY_STRING, FALLIBLE_TYPE_NESTED_ARRAY_STRING, FALLIBLE_TYPE_ARRAY_U8, FALLIBLE_TYPE_ARRAY_MAP,
    FALLIBLE_TYPE_STRUCT_DATABASE, FALLIBLE_TYPE_STRUCT_SOCKET, FALLIBLE_TYPE_STRUCT_LISTENER,
    FALLIBLE_TYPE_STRUCT_HTTP_RESPONSE, FALLIBLE_TYPE_STRUCT_MAP,
} FallibleType;

#define STDLIB_MAX_ARGUMENT_CHECKS 5

/* maximum_arguments sentinel for a variadic stdlib function (fmt.printf, sqlite.exec):
 * any argument count at or above minimum_arguments is accepted. */
#define STDLIB_ARGUMENTS_VARIADIC 99

typedef struct {
    const char *module_name;
    const char *function_name;
    int minimum_arguments;
    int maximum_arguments;
    bool is_fallible;
    FallibleType success_type;
    int argument_type_count;
    struct { int index; ExpectedArgumentKind kind; } argument_types[STDLIB_MAX_ARGUMENT_CHECKS];
    /* A type name; "$0" for argument 0's type, "$elem0" for its element
     * type, "[$0]" for an array of argument 0's type, "$common" for the
     * common type of the EXPECTED_ARGUMENT_COMMON_NUMBER arguments; or NULL when a
     * module resolver computes it. */
    const char *return_type;
} StdlibFunctionMetadata;

